  ui_story_5004_50040101_4_dialog_content = "(ริ้วสายฟ้าสีม่วงสลับแดงสว่างวาบขึ้นมาตัดกับท้องฟ้ามืดมัว ฟ้าร้องคำรามเสียงดังกึกก้องในหู)",
  ui_story_5004_50040101_5_dialog_content = "(ฉันจ้องมองอุกกาบาตจำนวนนับไม่ถ้วนร่วงหล่นใส่พวกเราจากเบื้องบน)",
  ui_story_5004_50040101_6_dialog_content = "(ปราสาทสีดำทะมึนอันน่าสะพรึงค่อย ๆ ลอยขึ้นช้า ๆ จากห้วงลึกของมหาสมุทร พร้อมนำความรู้สึกสลดหดหู่มาสู่ทุกคน)",
