  ui_story_5004_50040101_11_dialog_content = "เดี๋ยวสิ อยู่ ๆ ก็พาเด็กผู้หญิงมาให้ผมดูแลโดยไม่บอกล่วงหน้าแบบนี้ คุณเห็นผมเป็นอะไรเนี่ย!",
