  ui_story_5004_50040101_15_dialog_content = "ฉันชื่อ...",
  ui_story_5004_50040101_16_dialog_content = "เธอชื่้อ<color=#FFB400>เบริล</color> เอาล่ะ คราวนี้ทุกคนก็เป็นเพื่อนกันแล้วนะ",
  ui_story_5004_50040101_17_dialog_content = "หยุดเลย! คุณต้องอธิบายให้เคลียร์ก่อน! อย่าหนีนะ!",
  ui_story_5004_50040101_18_dialog_content = "ถ้าคุณยืนกรานว่า PlayerName, ฉันยินดีที่จะสอนคุณด้วยความจริง ...",
  ui_story_5004_50040101_19_dialog_content = "อย่าเปลี่ยนเรื่องสิ... ผมหมายถึง ก่อนหน้านี้คุณบอกผมด้วยนี่ ว่าเธอ...",
  ui_story_5004_50040101_20_dialog_content = "...",
