  ui_story_5004_50040101_28_dialog_content = "...",
  ui_story_5004_50040101_29_dialog_content = "อย่าเพิ่งไปนะครับ คุณเฟาสต์ ขอผมถามอีกเรื่อง",
  ui_story_5004_50040101_30_dialog_content = "คือว่า...",
  ui_story_5004_50040101_31_dialog_content = "เธอ...",
  ui_story_5004_50040101_32_option_content = "เป็นลูกสาวของคุณวิกตอเรียเหรอครับ?",
  ui_story_5004_50040101_33_dialog_content = "เข้าใจผิดแล้ว เลดี้วิกตอเรียอุทิศตนเพื่อแสวงหาสัจธรรมอย่างสุดกำลัง เธอไม่มีความปรารถนาทางโลกแบบนั้นหรอก",
  ui_story_5004_50040101_34_option_content = "เป็นเครื่องสังเวยในพิธีกรรมประหลาดของพวกคุณรึเปล่าเนี่ย?!",
  ui_story_5004_50040101_35_dialog_content = "แน่นอนว่าไม่ใช่อยู่แล้ว อย่าใส่ร้ายป้ายสีภารกิจแสวงหาสัจธรรมของพวกเราสิ",
  ui_story_5004_50040101_36_dialog_content = "แล้วเบริลเองก็เป็นสมาชิกคนสำคัญของทรู ออเดอร์ เหมือนกันนะ",
  ui_story_5004_50040101_37_dialog_content = "เอ่อ...",
  ui_story_5004_50040101_38_dialog_content = "โอเค ในเมื่อไม่มีแผนอะไรน่าสงสัย งั้นผมช่วยคุณก็ได้...",
  ui_story_5004_50040101_39_dialog_content = "แต่ยังไงผมก็ยังไม่เข้าใจอยู่ดี ว่าทำไมคุณวิกตอเรียเลือกผม",
  ui_story_5004_50040101_40_dialog_content = "นายไม่จำเป็นต้องเข้าใจการตัดสินใจของเธอหรอก",
  ui_story_5004_50040101_41_dialog_content = "ตราบใดที่ปฏิบัติตามคำสั่งของเธอ เราก็จะได้เข้าใกล้ความจริงมากยิ่งขึ้น",
  ui_story_5004_50040101_42_dialog_content = "(แบบนี้ยิ่งน่าสงสัยกว่าเดิมอีก...)",
  ui_story_5004_50040101_43_dialog_content = "เอาเถอะ ตอนนี้ราฟาเอลบังเอิญแวะมาที่โคลอสซัสพอดี ไปหาเธอหน่อยก็แล้วกัน",
