  ui_story_5004_50040101_47_dialog_content = "เป็นไงบ้าง?",
  ui_story_5004_50040101_48_dialog_content = "ฉันลองวินิจฉัยทุกวิธีแล้ว แต่ร่างกายเธอก็ไม่มีอะไรผิดปกติเลย",
  ui_story_5004_50040101_49_dialog_content = "เธอชื่อเบริลใช่มั้ย?",
  ui_story_5004_50040101_50_dialog_content = "ใช่ค่ะ",
  ui_story_5004_50040101_51_dialog_content = "เอาล่ะ เจ้าเบริล ตอนนี้รู้สึกเจ็บตรงไหนรึเปล่า?",
  ui_story_5004_50040101_52_dialog_content = "เจ้าเบริล...?",
  ui_story_5004_50040101_53_dialog_content = "ขอโทษนะ ฉันรับรู้อะไรที่เกิดขึ้นกับร่างกายตัวเองได้ช้าน่ะ",
  ui_story_5004_50040101_54_dialog_content = "แต่ช่วงนี้ฉันรู้สึกเหนื่อยมาก ๆ แล้วก็ควบคุมลูมินาของตัวเองลำบาก...",
  ui_story_5004_50040101_55_dialog_content = "บางทีก็รู้สึกปวดร้าวไปทั่วตัว เหมือนทั้งร่างกายโดนฝูงแมลงรุมกัด",
