  ui_story_5004_50040101_93_dialog_content = "อื้ม~ ได้เลย!",
  ui_story_5004_50040101_94_dialog_content = "แต่เรายังไม่รู้เลยว่าเจ้าเบริลป่วยเป็นอะไร",
