  ui_story_5004_50040101_95_dialog_content = "เธอรักษาอาการทางจิตเวชได้ด้วยเหรอ? ไม่ได้เป็นแค่นางฟ้านักรบที่ยิงจรวดได้อย่างเดียวสินะ!",
  ui_story_5004_50040101_96_dialog_content = "อย่าดูถูกฝีมือของเทวทูตแห่งลูโมโพลิสเชียวล่ะ เจ้าไวซ์!",
  ui_story_5004_50040101_97_dialog_content = "(ดูเหมือนราฟาเอลจะสนิทกับไวซ์อยู่แล้วแฮะ ยอดเลย)",
