  ui_story_5004_50040101_102_dialog_content = "เอโฮะส่งมาให้ก่อนจะวิ่งไปส่งของที่อื่นต่อน่ะ ที่ซองมีชื่อ<color=#FFB400>โรงแรมทีร์</color>เขียนอยู่",
