  ui_story_5004_50040101_118_dialog_content = "เราขอเชิญให้คุณมาพักผ่อนที่โรงแรมทีร์ในวันหยุดพักร้อนที่กำลังจะมาถึง",
  ui_story_5004_50040101_X118_dialog_content = "มาร่วมสนุกกับเทศกาล<color=#FFB400>ราชันเจ้าสมุทร</color>อันแสนตื่นเต้น พร้อมกิจกรรมต่าง ๆ ที่เราตั้งใจจัดเตรียมเพื่อคุณ",
