  ui_story_5004_50040201_13_dialog_content = "ไม่นึกเลยว่านายจะเป็นสุภาพบุรุษขนาดนี้นะเนี่ย PlayerName",
  ui_story_5004_50040201_14_dialog_content = "มองทางก่อน! มือจับพวงมาลัยด้วย!",
  ui_story_5004_50040201_15_dialog_content = "อย่าปอดแหกไปเลยน่า คนของเรดีเซล เวรนช์ ทุกคนเกิดมาเพื่อขับรถอยู่แล้ว!",
