  ui_story_5004_50040201_17_dialog_content = "โชคดีมากเลยนะเนี่ย ที่<color=#FFB400>รถ</color>ของ<color=#FFB400>บร็อค</color>จอดอยู่ในอู่พอดี ไม่งั้นนายต้องเดิน...",
  ui_story_5004_50040201_18_dialog_content = "ระวัง!",
