  ui_story_5004_50040201_20_dialog_content = "หือ?",
  ui_story_5004_50040201_21_dialog_content = "โอ๊ย! หนอย พวกอิคลิพไซท์บ้านี่มันโผล่มาจากไหนเนี่ย! ไม่ได้ขับรถมาตั้ง 20 ปีแล้ว พอจับพวงมาลัยปุ๊บก็เจอแบบนี้เลยเรอะ...",
  ui_story_5004_50040201_22_dialog_content = "กรรรรรรร!",
  ui_story_5004_50040201_23_dialog_content = "โอย เวียนหัวจัง... เมื่อกี้อิคลิพไซท์โดนชนกระเด็นไปแล้วใช่มั้ย?",
  ui_story_5004_50040201_24_dialog_content = "ทุกคนไม่เป็นไรนะ?",
