  ui_story_5004_50040201_26_dialog_content = "กรร!",
  ui_story_5004_50040201_27_dialog_content = "อิคลิพไซท์พวกนั้นมาจากไหนน่ะ? ทุกคน! เตรียมตัวนะ!",
