  ui_story_5004_50040201_43_dialog_content = "ปล่อยคริสตัลจำนวนมหาศาลเพื่อกำจัดอิคลิพไซท์ในพริบตา พลังทัดเทียมกับเทวทูตลูโมโพลิสเลยนะเนี่ย",
  ui_story_5004_50040201_44_dialog_content = "ใช่",
  ui_story_5004_50040201_45_dialog_content = "ยอดไปเลย... ขอบคุณนะ เจ้าเบริล!",
