  ui_story_5004_50040301_4_dialog_content = "อ้าว พวกนายมาทำอะไรที่นี่น่ะ?",
  ui_story_5004_50040301_5_dialog_content = "เอ๊ะ... แล้วทำไมรถฉันฝากระโปรงบุบล่ะ?",
