  ui_story_5004_50040301_13_dialog_content = "แหงอยู่แล้ว ฉันไม่ได้โง่นะ! มองแว้บเดียวก็รู้แล้ว!",
  ui_story_5004_50040301_14_option_content = "ฉันซ่อมรถให้นายเสร็จแล้ว ก็เลยขับมาส่งให้ถึงที่ไง!",
  ui_story_5004_50040301_15_dialog_content = "จริงเหรอ? ฉันเคยบอกด้วยเหรอว่าจะมาที่นี่?",
  ui_story_5004_50040301_16_dialog_content = "ฉันใช้พลังจิตอ่านใจดูน่ะ ใช่ พลังจิต!",
