  ui_story_5004_50040301_82_dialog_content = "\"ท้องทะเลคือต้นกำเนิดของสรรพชีวิตทั้งมวล ดูแลและฟูมฟักทุกสิ่งในอ้อมกอด\"",
  ui_story_5004_50040301_83_dialog_content = "\"เทพีแห่งท้องทะเลจะร่วมร่ายรำกับผู้กล้าทั้งหลายที่รับคำท้าทาย\"",
  ui_story_5004_50040301_84_dialog_content = "ในงานราชันเจ้าสมุทร ผู้เข้าแข่งขันจะได้เผชิญกับบททดสอบในตำนาน",
