  ui_story_5004_50040301_86_dialog_content = "เทพเจ้าจะมอบรางวัลแก่ผู้ชนะ และมอบพรอันเป็นมงคลแก่ดินแดนอันงดงามแห่งนี้ เพื่อคลื่นลมที่สงบ และสัตว์ทะเลอันอุดมสมบูรณ์",
  ui_story_5004_50040301_87_dialog_content = "นอกจากนี้ ผู้ชนะเลิศจะได้รับตำแหน่ง<color=#FFB400>ผู้กล้าแห่งหาดทราย</color>",
  ui_story_5004_50040301_88_dialog_content = "พร้อมรางวัลใหญ่ปริศนาที่ฉันขอเก็บเป็นความลับ!",
