  ui_story_5004_50040501_36_dialog_content = "แต่อาจจะยังไม่ชินเท่าไหร่",
  ui_story_5004_50040501_37_dialog_content = "ฮะฮะฮะ แขกหลายคนก็เป็นแบบนี้เหมือนกัน พวกเขาไม่ชินกับการเดินทางเท่าไหร่",
  ui_story_5004_50040501_38_dialog_content = "สมัยนี้คนเรารู้สึกว่าอยู่บ้านแล้วจะปลอดภัยกว่า ยิ่งในยุคสมัยที่อิคลิพไซท์ออกเพ่นพ่านไปทั่วแบบนี้",
