  ui_story_5004_50040601_46_dialog_content = "แดดวันนี้แรงอยู่ แต่ได้อาบแดดบ้างก็ดีเหมือนกัน",
  ui_story_5004_50040601_47_dialog_content = "ไวซ์กับทุก ๆ คนก็เหมือนกับเพื่อนเก่า... พวกเราได้มาเที่ยวเล่นโดยไม่ต้องกังวลเรื่องอิคลิพไซท์แล้วก็แผนชั่วของศัตรู...",
  ui_story_5004_50040601_48_dialog_content = "เพลิดเพลินกับสายลมและแสงแดดอย่างสงบ... ยอดไปเลย!",
