  ui_story_5004_50040601_65_dialog_content = "(ดูเหมือนคาร์ลีนก็ตื่นเต้นที่ได้มาเที่ยวเหมือนกัน ถึงเหตุผลจะไม่เหมือนไวซ์ก็เถอะ...)",
  ui_story_5004_50040601_66_dialog_content = "(แต่ว่า ถึงกับบอกให้ฉันมองชุดว่ายน้ำแบบนี้ เธอจะตื่นเต้นมากไปหน่อยรึเปล่านะ)",
