  ui_story_5004_50040601_69_dialog_content = "ชุดว่ายน้ำไงล่ะ นายคิดว่าผู้กล้าที่พิชิตชายหาดแห่งนี้จะเป็นใคร?",
  ui_story_5004_50040601_70_option_content = "ไวซ์ในชุดว่ายน้ำดูร่าเริงแล้วก็น่ารักดี",
