  ui_story_5004_50040701_170_dialog_content = "เอ้า เครื่องดื่มของนายได้แล้ว ฉันใส่น้ำแข็งเพิ่มให้ด้วย ดื่มให้อร่อยนะ!",
  ui_story_5004_50040701_171_dialog_content = "เห็นมั้ย ฉันน่ะ พูดคำไหนคำนั้น... พรวดด!!!",
