  ui_story_5004_50040901_40_dialog_content = "พลังนั่นทำให้คนบาดเจ็บ! แล้วก็ไม่ใช่แค่คนเดียวด้วย! ทำไมต้องปกปิดเรื่องให้ท้ายเจ้านั่นด้วย?",
