  ui_story_5004_50040901_57_dialog_content = "อืม ฉันช่วยเธอจัดงานราชันเจ้าสมุทรได้ แต่เธอลบล้างพลังพิเศษของฉันได้จริง ๆ น่ะเหรอ?",
  ui_story_5004_50040901_58_dialog_content = "ไม่ต้องห่วง ฉันเจอข้อมูลบางอย่างจากซากโบราณสถาน ถ้าตำนานเป็นจริง มันก็มีวิธีอยู่",
  ui_story_5004_50040901_59_dialog_content = "อา ชายหนุ่มคนนี้คือเฟลอร์สินะ นายจะต้องรับตำแหน่งผู้จัดการ และมีหน้าที่เตรียมงานราชันเจ้าสมุทร",
  ui_story_5004_50040901_59X1_dialog_content = "เข้าใจแล้ว ผมจะเริ่มงานเดี๋ยวนี้ล่ะ",
  ui_story_5004_50040901_59X2_dialog_content = "เริ่มต้นได้สวย เอ้อ แล้วตำนานที่เธอบอกนี่มันอะไรกัน?",
  ui_story_5004_50040901_59X3_dialog_content = "ฉันแต่งเรื่องขึ้นมาเฉย ๆ น่ะ เอาเถอะ ตราบใดที่ล่อพวกนั้นมาได้ จะใช้วิธีไหนมันก็ไม่ต่างกันหรอก",
  ui_story_5004_50040901_59X4_dialog_content = "หึหึ ถูกต้อง ตราบใดที่พาทุกคนในรายชื่อมาที่นี่สำเร็จ...",
  ui_story_5004_50040901_59X5_dialog_content = "งานราชันเจ้าสมุทร... ฉันจะต้องคว้าโอกาสนี้ให้ได้",
  ui_story_5004_50040901_60_dialog_content = "ฉันพร้อมแล้ว...",
  ui_story_5004_50040901_61_dialog_content = "ลุยเลย เฟลอร์!",
  ui_story_5004_50040901_62_dialog_content = "เฟลอร์!",
  ui_story_5004_50040901_63_dialog_content = "<size=45>คุณเฟลอร์!</size>",
  ui_story_5004_50040901_64_dialog_content = "อรุณสวัสดิ์ ทุกคน",
  ui_story_5004_50040901_65_dialog_content = "กลิ่นหอมจังเลย คุณเฟลอร์!",
  ui_story_5004_50040901_66_dialog_content = "เมื่อกี้อาบน้ำอยู่เหรอ? ฉันได้ยินเสียงฝักบัวด้วย!",
  ui_story_5004_50040901_67_dialog_content = "โอ๊ะ เอ่อ ช่วยหลีกทางหน่อยได้มั้ยครับ?",
  ui_story_5004_50040901_68_dialog_content = "ฉันขอเข้าห้องนายได้มั้ย?",
  ui_story_5004_50040901_69_dialog_content = "ขอโทษครับ ผมอยากให้อะไหล่เครื่องจักรทุกชิ้นในห้องอยู่ที่เดิม เพราะงั้น...",
  ui_story_5004_50040901_70_dialog_content = "เฟลอรี่ ครูสอนโยคะบอกว่าถ้าฉันสมัครคอร์ส ฉันจะได้ออกกำลังกับนายในคลาส เป็นความจริงรึเปล่า?",
  ui_story_5004_50040901_71_dialog_content = "งั้นรึ? ผมว่าคุณโดนหลอกแล้วล่ะ...",
  ui_story_5004_50040901_72_dialog_content = "ทุกคน เงียบก่อนเถอะครับ ขอบคุณมากเลย แต่ผมนัดคนไว้ เพราะงั้นช่วยหลีกทางหน่อยเถอะครับ...",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>หา?</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "ใครกันน่ะ? แอบดอดมาขโมยเฟลอร์ของฉัน เจ้าเล่ห์นักนะ!",
  ui_story_5004_50040901_75_dialog_content = "คุณเฟลอร์ มาเดตกับฉันดีกว่าน่า",
  ui_story_5004_50040901_76_dialog_content = "(ให้ตายสิ คงต้องให้ PlayerName รอซะแล้ว)",
  ui_story_5004_50041001_1_dialog_content = "เข้าใจล่ะ แบบนี้นี่เอง!",
  ui_story_5004_50041001_2_dialog_content = "ขอโทษด้วยที่มาช้า ฉันขอบคุณจริง ๆ ที่อุตส่าห์รอนะ",
  ui_story_5004_50041001_3_dialog_content = "ไม่เป็นไรหรอก ผมไม่ได้รอนานขนาดนั้นหรอกครับ ว่าแต่ เฟลอร์ คุณจะสร้างหุ่นยนต์จริง ๆ เหรอ?",
  ui_story_5004_50041001_4_dialog_content = "ใช่ นั่นเป็นความฝันของฉันเลย",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก</color>",
  ui_story_5004_50041001_6_dialog_content = "ขอคุยด้วยหน่อยสิ PlayerName",
  ui_story_5004_50041001_7_dialog_content = "ได้ครับ",
  ui_story_5004_50041001_8_dialog_content = "อ้าว เฟลอร์ก็มาด้วยเหรอ",
  ui_story_5004_50041001_9_dialog_content = "นายเป็นหัวหน้าทีมวางแผนจัดงานราชันเจ้าสมุทรนะ อย่าอู้งานสิ",
  ui_story_5004_50041001_10_dialog_content = "ฉันไม่ได้อู้ซักหน่อย ก็แค่มาถามความคิดเห็นเรื่องการออกแบบกับ PlayerName น่ะ",
  ui_story_5004_50041001_11_dialog_content = "ฉันจะกลับไปทบทวนแบบแปลนอีกรอบเดี๋ยวนี้ล่ะ แล้วเจอกัน",
  ui_story_5004_50041001_12_dialog_content = "PlayerName ตัดสินใจได้รึยัง? สรุปแล้วนายอยากลงแข่งในงานราชันเจ้าสมุทรรึเปล่า? ปีนี้รางวัลของเรา...",
