  ui_story_5004_50041001_14_dialog_content = "หืม?",
  ui_story_5004_50041001_15_dialog_content = "ไม่มีปัญหาอะไรใช่มั้ย? ผมปรึกษากับเพื่อน ๆ แล้ว...",
  ui_story_5004_50041001_16_dialog_content = "เกินคาดแฮะ ฉันนึกว่านายจะใช้เวลาคิดนานกว่านี้ซะอีก!~",
  ui_story_5004_50041001_17_dialog_content = "มันก็แค่งานเทศกาลธรรมดานี่นา มีอะไรต้องคิดด้วยเหรอ?",
  ui_story_5004_50041001_18_dialog_content = "แล้ว PlayerName ไม่กลัวว่าจะมีคนวางแผนชั่วอยู่เบื้องหลังเหรอ?",
  ui_story_5004_50041001_19_dialog_content = "แผนชั่ว? งั้นผมไม่แข่งแล้ว!",
  ui_story_5004_50041001_20_dialog_content = "ฮะฮะฮะ~ น่ารักจัง ถึงฉันจะเป็นสมาชิกทรู ออเดอร์ แต่ก็คงไม่เปิดเผยแผนสมคบคิดออกมาตรง ๆ แบบนี้หรอกนะ!",
  ui_story_5004_50041001_21_dialog_content = "ฉันแค่ปล่อยมุกหยอกเล่นเฉย ๆ เป็นรางวัลที่นายตัดสินใจได้ถูกต้องไงล่ะ",
  ui_story_5004_50041001_22_dialog_content = "(ทรู ออเดอร์ มีแต่คนเพี้ยน ๆ หรือไงเนี่ย?)",
  ui_story_5004_50041001_23_dialog_content = "ในเมื่อตัดสินใจได้แล้วก็เซ็นชื่อในเอกสารได้เลย",
  ui_story_5004_50041001_24_dialog_content = "เอ้า นี่ปากกา",
  ui_story_5004_50041001_25_dialog_content = "โอ้โห สวยจังเลย",
  ui_story_5004_50041001_26_dialog_content = "ทำไมเย็นเหมือนน้ำแข็งเลยล่ะ",
  ui_story_5004_50041001_27_dialog_content = "มันทำจากคริสตัลหายากน่ะ แพงมากเลยนะรู้มั้ย",
  ui_story_5004_50041001_28_dialog_content = "ถึงจะเป็นแค่ปากกาด้ามเล็ก ๆ แต่มูลค่าของมันเท่ากับครึ่งนึงของโรงแรมเชียวนะ",
  ui_story_5004_50041001_29_dialog_content = "ถ้า PlayerName สนใจปากกานี่ขนาดนั้น ฉันให้นายเป็นของขวัญก็ได้",
  ui_story_5004_50041001_30_dialog_content = "หา! ผมรับของขวัญแพงขนาดนี้ไม่ได้หรอก!",
  ui_story_5004_50041001_31_dialog_content = "ไม่เป็นไรหรอกน่า ยังไงมันก็เป็นของที่ขุดได้จากซากโบราณ",
  ui_story_5004_50041001_32_dialog_content = "สมกับเป็นทรู ออเดอร์ ที่ชอบสำรวจโบราณสถานทุกแห่งจริง ๆ!",
  ui_story_5004_50041001_33_dialog_content = "ขอบคุณที่ชมนะ~ ว่าแต่ ฉันรู้มาว่าอุปกรณ์ควบคุมโคลอสซัสของนาย... รูปร่างเหมือนเปียโนใช่มั้ย?",
  ui_story_5004_50041001_34_dialog_content = "ฉันเองเป็นนักดนตรี แล้วก็สนใจมันมาก ๆ ไม่รู้ว่าฉันจะมีโอกาสได้เห็นเป็นบุญตามั้ยนะ?",
  ui_story_5004_50041001_35_dialog_content = "วันหลังถ้าคุณแวะมาเดี๋ยวผมพาทัวร์ก็ได้ เอาล่ะ เซ็นเรียบร้อยแล้วครับ!",
  ui_story_5004_50041001_36_dialog_content = "อืม... ทุกอย่างเป็นอันตกลง จากนี้นายเป็นผู้เข้าแข่งขันอย่างเป็นทางการแล้วนะ",
  ui_story_5004_50041001_37_dialog_content = "แมตช์แรกจะเริ่มตอนบ่าย ไปพักผ่อนก่อนเถอะ",
  ui_story_5004_50041001_38_dialog_content = "ขอให้โชคดีในการแข่งขันนะ",
  ui_story_5004_50041001_39_dialog_content = "เอ ราบรื่นกว่าที่คิดแฮะ",
  ui_story_5004_50041001_40_dialog_content = "ความรู้สึกในใจฉันตอนนี้ คือความรู้สึกผิดรึเปล่านะ?",
