  ui_story_5004_50041001_X40X2_dialog_content = "ไม่นึกเลยว่า PlayerName จะยอมใช้ปากกาของ \"เจ้านั่น\" เซ็นชื่อง่าย ๆ...",
  ui_story_5004_50041001_X40X3_dialog_content = "อยากรู้จังว่า \"เจ้านั่น\" วางแผนอะไรอยู่... แต่ก็ช่างเถอะ แค่อิคลิพไซท์ไม่กี่ตัว พวกมันไม่มีปัญญาทำอะไรอยู่แล้ว",
