  ui_story_5004_50041101_4_dialog_content = "ข้าจะแสดงหนทางให้เจ้า... เพียงแค่นำ \"ผลไม้\" นั่นมาให้ข้า",
  ui_story_5004_50041101_5_dialog_content = "เจ้าไม่จำเป็นต้องเอาใจคนธรรมดาไร้ค่าพวกนั้นอีกต่อไป... และจะได้มุ่งสู่จุดสูงสุดแห่งดนตรีที่แท้จริง",
  ui_story_5004_50041101_6_dialog_content = "เข้าใจแล้ว... นี่ล่ะที่ฉันต้องการมาตลอด...!",
  ui_story_5004_50041101_7_dialog_content = "เห็นเธอพึมพำกับตัวเองทีไรก็รู้สึกแปลก ๆ ทุกที คราวนี้เสียงในหัวเธอว่ายังไงบ้าง?",
  ui_story_5004_50041101_8_dialog_content = "ในเมื่อเธอพาคนในรายชื่อมาที่นี่ได้ ฉันก็จะให้ท่อนเพลงครึ่งแรกกับเธอตามสัญญา",
  ui_story_5004_50041101_9_dialog_content = "หรือเสียงนั่นจะงอแงขอครึ่งที่เหลือกันล่ะ?",
