  ui_story_5004_50041101_13_dialog_content = "ขอบอกไว้เลยนะ เป้าหมายของฉันคือการรวบรวมท่อนเพลงเทพเจ้าให้ครบ แล้วฉันก็ไม่คิดจะร่วมมือกับอิคลิพไซท์อย่างพวกแก",
  ui_story_5004_50041101_14_dialog_content = "ที่ฉันทำตามคำขอก็เพราะแกให้ท่อนเพลงครึ่งแรกมา และสัญญาว่าจะให้ครึ่งหลังด้วย",
  ui_story_5004_50041101_15_dialog_content = "พวกเรามีผลประโยชน์ร่วมกันชั่วคราว ฉันไม่ได้คิดจะช่วยแกในระยะยาว เข้าใจมั้ย?",
  ui_story_5004_50041101_15X_dialog_content = "แล้วก็นะ อิคลิพไซท์ที่แกส่งไป โดน PlayerName กับออโรเรียนพวกนั้นจัดการหมดแล้ว",
  ui_story_5004_50041101_16_dialog_content = "เจ้าแฮมสเตอร์เปี๊ยกไร้ประโยชน์",
  ui_story_5004_50041101_17_dialog_content = "หนอย ยัยออโรเรียนโสโครกนี่!",
  ui_story_5004_50041101_18_dialog_content = "ใจเย็นน่า",
  ui_story_5004_50041101_19_dialog_content = "แกยังไม่อยากให้รังหนูเล็ก ๆ นี่โดนเปิดโปงตอนนี้ใช่มั้ยล่ะ?",
  ui_story_5004_50041101_20_dialog_content = "อุตส่าห์คิดแผนบ้า ๆ ขึ้นมาแล้วนี่? หลอกล่อนักท่องเที่ยวด้วยงานราชันเจ้าสมุทร แล้วก็ขายอัลบั้มภาพชุดว่ายน้ำเพื่อหาทุนสนับสนุนการรบ?",
  ui_story_5004_50041101_21_dialog_content = "แถมยังมีกลโกงหลอกฟันเงินนักท่องเที่ยวเต็มไปหมด อย่างคอร์สโยคะอะไรนั่น",
  ui_story_5004_50041101_22_dialog_content = "แต่สุดท้ายเงินส่วนใหญ่ก็ต้องส่งไปให้หัวหน้าตัวจริงที่คุมแกอยู่สินะ",
  ui_story_5004_50041101_23_dialog_content = "ส่วนหัวหน้าจอมปลอมอย่างแก ก็เป็นได้แค่เครื่องมือ",
  ui_story_5004_50041101_24_dialog_content = "ถ้าเพื่อน ๆ อิคลิพไซท์รู้ว่าแกทำงานให้ออโรเรียน แกคงโดนล้อไม่ได้ผุดได้เกิดแน่",
