  ui_story_5004_50041101_28_dialog_content = "ส่งแขกให้ทีซิ อาจารย์แทดเดียส",
  ui_story_5004_50041101_29_dialog_content = "เชิญครับ",
  ui_story_5004_50041101_30_dialog_content = "ระหว่างทางกลับ ผมขออนุญาตนำเสนอคลาสโยคะล่าสุด",
  ui_story_5004_50041101_31_dialog_content = "ความสมบูรณ์แบบเริ่มต้นจากทัศนคติ ความสง่างามเกิดขึ้นได้จากการใช้ชีวิต และจิตใจที่แข็งแกร่งเกิดขึ้นได้จากการมองโลกอย่างถูกต้อง ชีวิตที่สวยงามเริ่มต้นได้ด้วยโยคะ",
