  ui_story_5004_50041201_1_dialog_content = "สนามแข่งอยู่นี่เอง",
  ui_story_5004_50041201_2_dialog_content = "เก้าอี้กรรมการ แล้วก็ตาข่าย... ตรงกับในคลังข้อมูลของโซรอซเลย",
  ui_story_5004_50041201_2X1_dialog_content = "เอ๊ะ นั่นอะไรน่ะ?",
  ui_story_5004_50041201_2X2_dialog_content = "ไม่ต้องไปสนใจหรอก~ ก็แค่อุปกรณ์จำกัดความเสียหายน่ะ",
  ui_story_5004_50041201_2X3_dialog_content = "ของพวกนี้จะช่วยป้องกันไม่ให้บริเวณรอบข้างเละเทะ ถ้าเกิดการต่อสู้มันดุเดือดขึ้นมา",
  ui_story_5004_50041201_2X4_dialog_content = "(หา? เราแค่มาเล่นวอลเลย์บอลเฉย ๆ ไม่ใช่เหรอ?)",
  ui_story_5004_50041201_2X5_dialog_content = "ฟู่ เรียบร้อย",
  ui_story_5004_50041201_3_dialog_content = "เอาล่ะ กรรมการก็เข้าประจำตำแหน่งแล้ว",
  ui_story_5004_50041201_4_dialog_content = "ขอต้อนรับทุกท่านเข้าสู่กิจกรรมแรกของงานราชันเจ้าสมุทร การแข่งขันวอลเลย์บอลซึ่งเป็นตัวแทนของความแข็งแกร่งและความกล้าหาญ!",
  ui_story_5004_50041201_5_dialog_content = "ฝั่งขวา เชิญพบกับทีมของ PlayerName",
  ui_story_5004_50041201_6_dialog_content = "นี่ เฟลอร์ นายอยู่ทีมเดียวกับ PlayerName ไม่ใช่เหรอ รีบมายืนประจำที่ได้แล้ว",
  ui_story_5004_50041201_7_dialog_content = "หา เฟลอร์ก็มาร่วมงานด้วยเหรอ",
  ui_story_5004_50041201_8_dialog_content = "ฉันไม่ได้เล่นกีฬากับบร็อคนานแล้วน่ะ เลยอยากมายืดเส้นยืดสายซักหน่อย แล้วโบนาชีก็เอาแต่รบเร้าด้วย",
  ui_story_5004_50041201_9_dialog_content = "เอาหมอนี่มาแบบนี้ คนดูไม่เป็นบ้ากันไปหมดเรอะ...",
  ui_story_5004_50041201_10_dialog_content = "เฟลอร์!",
  ui_story_5004_50041201_11_dialog_content = "เฟลอรี่!",
  ui_story_5004_50041201_12_dialog_content = "นั่นสิ...",
  ui_story_5004_50041201_13_dialog_content = "ฉันเล่นกีฬาไม่เก่งซะด้วย...",
  ui_story_5004_50041201_14_dialog_content = "ไม่เป็นไร PlayerName ฉันเล่นวอลเลย์บอลเก่งมาก ๆ เลย!",
  ui_story_5004_50041201_15_dialog_content = "ใช่แล้ว สมัยเรียนเธอทำคะแนนวิชาพละได้ดีมาก ๆ",
  ui_story_5004_50041201_16_dialog_content = "ที่ได้ฉายา<color=#FFB400>แม่สาวกระดูกเหล็กกล้า-มือโลหะ</color>น่ะ ไม่ใช่เรื่องบังเอิญหรอกนะ",
  ui_story_5004_50041201_17_dialog_content = "วางใจได้เลย PlayerName งานนี้ให้เราจัดการเอง",
  ui_story_5004_50041201_18_dialog_content = "(ฉายาที่นักเรียนลูโมโพลิสคิดขึ้นมานี่มันพิลึกจัง)",
  ui_story_5004_50041201_19_dialog_content = "งั้นเหรอ? ยอดไปเลย ฝากด้วยนะ! ไวซ์!",
  ui_story_5004_50041201_20_dialog_content = "ชิ ไม่นึกเลยว่าจะต้องอยู่ทีมเดียวกับนายนะเนี่ย",
  ui_story_5004_50041201_21_dialog_content = "เอ๊ะ คุณผู้หญิงคนเมื่อวาน... นี่คุณก็ลงแข่งด้วยเหรอ?",
  ui_story_5004_50041201_22_dialog_content = "เธอนี่แหละ ที่ทำปราสาททรายของเจ้าเบริลพัง!",
  ui_story_5004_50041201_23_dialog_content = "ทำไม? ฉันลงแข่งด้วยไม่ได้หรือไง? โบนาชีเป็นคนชวนฉันเองนะ!",
  ui_story_5004_50041201_24_dialog_content = "อีกอย่างนะ ฉันชื่อสโมกกี้ แล้วฉันก็ขอโทษเรื่องปราสาททรายไปแล้ว",
  ui_story_5004_50041201_25_dialog_content = "อย่าเพิ่งทะเลาะกันเลยน่า ไหน ๆ ก็อยู่ทีมเดียวกันแล้ว ถ้าอยากชนะเราก็ต้องร่วมมือกัน",
  ui_story_5004_50041201_26_dialog_content = "เนี่ยเหรอผู้หญิงหัวร้อนที่นายพูดถึงเมื่อวาน? จะไหวมั้ยเนี่ย...",
  ui_story_5004_50041201_27_dialog_content = "ใช่ แต่ฉันว่า<color=#FFB400>ผู้หญิงอีกคน</color>คุยยากกว่านี้อีก",
  ui_story_5004_50041201_28_dialog_content = "ฝั่งซ้าย ขอเชิญพบกับเจเนวีฟกับเหล่าแฟนเดนตายของเธอ!",
  ui_story_5004_50041201_29_dialog_content = "ฮึ่ม!",
  ui_story_5004_50041201_30_dialog_content = "นั่นไง!",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>ฮูเร่ ฮูเร่ ฮูเร่!</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "หึหึ เห็นรึยัง สโมกกี้?",
  ui_story_5004_50041201_33_dialog_content = "ชนชั้นสูงที่แท้จริงจะต้องเป็นที่รักของสามัญชนเสมอ ไม่ว่าจะไปที่ไหน",
  ui_story_5004_50041201_34_dialog_content = "พวกเขาตระหนักถึงสถานะอันสูงส่งของฉันจากบุคลิกอันสง่างาม และยอมสยบภายใต้ความแข็งแกร่งของฉัน!",
  ui_story_5004_50041201_35_dialog_content = "ซึ่งนั่นเป็นสิ่งที่เธอไม่มีวันเข้าใจ สโมกกี้!",
  ui_story_5004_50041201_36_dialog_content = "โอเค เอาเถอะ เอาเถอะ",
  ui_story_5004_50041201_37_dialog_content = "ใครมันจะอยากเข้าใจเรื่องน่าเบื่อพวกนี้กัน",
  ui_story_5004_50041201_38_dialog_content = "นี่ ใส่ให้สุดฝีมือเลยนะทุกคน มาเริ่มกันเถอะ!",
  ui_story_5004_50041201_39_dialog_content = "จะตายอยู่แล้วแท้ ๆ ยังทำตัวจองหองอีกรึ... งั้นเจอนี่หน่อยเป็นไง...",
  ui_story_5004_50041201_40_dialog_content = "เดี๋ยวสิ แมตช์ยังไม่เริ่มเลยนะ!",
  ui_story_5004_50041201_41_dialog_content = "ชิ",
  ui_story_5004_50041201_42_dialog_content = "ว้าว ปฏิกิริยาตอบสนองเร็วชะมัด!",
  ui_story_5004_50041201_43_dialog_content = "!!!",
  ui_story_5004_50041201_44_dialog_content = "(หลังจากสโมกกี้หลบได้ บอลก็พุ่งตรงเข้าหาฉัน)",
  ui_story_5004_50041201_45_dialog_content = "(ถึงนี่จะเป็นแค่เกมวอลเลย์บอล แต่ในวินาทีนั้น ฉันก็ปรารถนาอยากจะมีพลังต่อสู้ยิ่งกว่าครั้งไหน)",
  ui_story_5004_50041201_46_dialog_content = "(ลูกตบสังหารนั่น น่ากลัวกว่าการเผชิญหน้ากับอิคลิพไซท์ตรง ๆ ซะอีก)",
  ui_story_5004_50041201_47_dialog_content = "(ฉันหลับตาลง ภาพชีวิตในอดีตย้อนผ่านเข้ามาในความคิด)",
  ui_story_5004_50041201_48_dialog_content = "(ถ้าฉันกระเด็นตกทะเล หวังว่าไวซ์จะรีบมาช่วยเร็ว ๆ นะ)",
  ui_story_5004_50041201_49_dialog_content = "อยากรู้จังว่าน้ำทะเลมันจะรสชาติเป็นยังไง?",
  ui_story_5004_50041201_50_dialog_content = "PlayerName!",
  ui_story_5004_50041201_51_dialog_content = "ไวซ์ เธอไม่เป็นไรใช่มั้ย?!",
  ui_story_5004_50041201_52_dialog_content = "ไม่เป็นไร ไม่ต้องห่วง แต่ก็เกือบโดนกระแทกออกนอกสนามแน่ะ",
  ui_story_5004_50041201_53_dialog_content = "นี่ แมตช์ยังไม่เริ่มเลย แบบนี้มันผิดกติกานะ เจเนวีฟ!",
  ui_story_5004_50041201_54_dialog_content = "PlayerName นายอ่านคู่มือที่ฉันให้ไปรึเปล่าเนี่ย?",
  ui_story_5004_50041201_55_dialog_content = "ใครจะมีเวลานั่งอ่านหนังสือหนา ๆ ที่มีแต่โฆษณากันล่ะ?",
  ui_story_5004_50041201_56_dialog_content = "งั้นอย่ามาโทษฉันก็แล้วกัน",
  ui_story_5004_50041201_57_dialog_content = "พยายามเข้าล่ะทุกคน! จงแสดงความกล้าหาญให้เทพเจ้าได้ประจักษ์ และต่อสู้จนถึงวินาทีสุดท้าย!",
  ui_story_5004_50041201_58_dialog_content = "(ฉันมันซื่อบื้อเกินไป ที่คิดว่านี่จะเป็นเกมวอลเลย์บอลที่รู้จัก)",
  ui_story_5004_50041201_59_dialog_content = "(นี่มันสงครามชายหาดเต็มรูปแบบชัด ๆ)",
  ui_story_5004_50041202_1_dialog_content = "ฉัน... ยังไม่แพ้... หรอก...",
  ui_story_5004_50041202_2_dialog_content = "มีฝีมือแค่นี้เองรึ?",
  ui_story_5004_50041202_3_dialog_content = "ขอโทษนะ PlayerName ถ้ารู้ว่าเป็นแบบนี้ ฉันน่าจะเอาหอกดักแด้จันทรามาด้วย...",
  ui_story_5004_50041202_4_dialog_content = "ไม่เป็นไรหรอก หอกเธอจะเจาะลูกวอลเลย์เป็นรูอยู่ดีนั่นแหละ เรายังมีบร็อคกับคนอื่น ๆ อยู่ พวกเธอเก็บแรงไว้ดีกว่า",
  ui_story_5004_50041202_5_dialog_content = "นี่ พวกนาย ตั้งใจกว่านี้หน่อยได้มั้ย!",
  ui_story_5004_50041202_6_dialog_content = "งั้นก็อย่าเอาแต่พูดสิ!",
  ui_story_5004_50041202_7_dialog_content = "เฮ้ ตาดูลูกด้วย!",
  ui_story_5004_50041202_8_dialog_content = "ขอบใจนะ บร็อค!",
  ui_story_5004_50041202_9_dialog_content = "ตั้งฟอร์เมชั่น แล้วส่งลูกให้เจเนวีฟ!",
  ui_story_5004_50041202_10_dialog_content = "<size=45>นั่นล่ะ!</size>",
  ui_story_5004_50041202_11_dialog_content = "เจเนวีฟไม่สนฉันเลยแฮะ นี่ฉันไร้น้ำยาขนาดนั้นเลยเหรอ?",
  ui_story_5004_50041202_12_dialog_content = "สถานการณ์วิกฤตแล้วสิ ได้เวลาเอา<color=#FFB400>ไอ้นั่น</color>ออกมาแล้ว!",
  ui_story_5004_50041202_13_dialog_content = "เดี๋ยวนะ จะทำอะไรน่ะ?",
  ui_story_5004_50041202_14_dialog_content = "นั่นมัน<color=#FFB400>แขนจักรกล</color>ไม่ใช่เรอะ?",
  ui_story_5004_50041202_15_dialog_content = "ฮะฮะ เข้าใจผิดแล้ว มันก็แค่<color=#FFB400>แขนของฉัน</color>เฉย ๆ",
  ui_story_5004_50041202_16_dialog_content = "มันคือ \"ดูม RX100\" ที่ฉันช่วยกันสร้างกับเจ้าจิ๋วน่ะ แล้วก็เพิ่มพลังให้แรงสามเท่ามาแล้วด้วย!",
  ui_story_5004_50041202_17_dialog_content = "\"ดูม\" เหรอ? นั่นมันชื่อแขนกลของโจนานี่นา?",
  ui_story_5004_50041202_18_dialog_content = "ที่ต่างกันก็แค่พ่นสีแดงตรงกำปั้นเฉย ๆ มันจะแรงขึ้นสามเท่าได้ไงฟะ??",
  ui_story_5004_50041202_19_dialog_content = "มือขวาของฉันกำลังลุกโชติช่วงด้วยเพลิงแห่งชัยชนะ!",
  ui_story_5004_50041202_20_dialog_content = "เลิกพูดประโยคแปลก ๆ ได้แล้ว แขนนายไม่ได้ผลหรอกน่า",
  ui_story_5004_50041202_21_dialog_content = "ความแม่นยำและพละกำลังของแขนข้างนี้ไม่มีทางแพ้ใคร!",
  ui_story_5004_50041202_22_dialog_content = "แหงสิฟะ! ก็มันทำเหล็กนี่หว่า!",
  ui_story_5004_50041202_23_dialog_content = "ถึงไม่มีบอล แต่เจ้านี่ก็สามารถซัดคนที่อยู่ห่างออกไปหลายเมตรได้เลยนะ",
  ui_story_5004_50041202_24_dialog_content = "ฉันกลัวว่ามันจะแข็งแกร่งเกินไปน่ะสิ...",
  ui_story_5004_50041202_25_dialog_content = "ถอดแขนกลนั่นออกเถอะ ไม่งั้นเราจะโดนปรับแพ้นะ!",
  ui_story_5004_50041202_26_dialog_content = "ยังไม่ยอมให้ใช้อีกเหรอ... บร็อค นายนี่มันไม่เข้าใจอะไรเลยนะ",
  ui_story_5004_50041202_27_dialog_content = "ระวัง!",
  ui_story_5004_50041202_28_dialog_content = "เจอช่องว่างแล้ว!",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>ผัวะ ผัวะ!</color>",
  ui_story_5004_50041202_30_dialog_content = "โอ๊ย... อึก...",
  ui_story_5004_50041202_31_dialog_content = "อา... ไม่ไหวแล้ว... ท้องฟ้าช่างงดงามเหลือเกิน...",
  ui_story_5004_50041202_32_dialog_content = "บร็อคโดนอัดจมทรายไปแล้ว! นี่มันวอลเลย์บอลจริง ๆ เหรอ?!",
  ui_story_5004_50041202_33_dialog_content = "เกมแรกจบลงแล้ว ต่อไปเข้าสู่ช่วงพักครึ่ง",
  ui_story_5004_50041202_34_dialog_content = "ในระหว่างนี้ ขอให้ทุกท่านเพลิดเพลินกับสปอนเซอร์ของเรา!",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "ขอแนะนำแพ็กประจำฤดูกาลสุดฮ็อตจากกิลด์เหนือเมฆ",
  ui_story_5004_50041202_36_dialog_content = "แตะไอคอนเพื่อรับข้อเสนอพิเศษจากโบนาชีได้เลย พร้อมรับโบนัสเป็นสตาร์แฟลร์สีฟ้าฟรี 10 ก้อน!",
  ui_story_5004_50041202_37_dialog_content = "นอกจากนี้ยังมีแทงก์เก็บน้ำแบบเป่าลมสำหรับปืนฉีดน้ำ เหมาะสุด ๆ สำหรับชายหาด!",
  ui_story_5004_50041202_38_dialog_content = "ด่วน สินค้ามีจำนวนจำกัดเพียง 5,000... ไม่สิ ตอนนี้เหลือเพียง 1,001 ชิ้นแล้ว!",
  ui_story_5004_50041202_39_dialog_content = "รีบคว้ามาเป็นเจ้าของก่อนพลาดโอกาส!",
  ui_story_5004_50041202_40_dialog_content = "ให้ตายสิ แค่ 10 วินาทีก็ขายหมดซะแล้ว!",
  ui_story_5004_50041202_41_dialog_content = "เอาล่ะ ถ้าอย่างนั้น โปรดติดตามช้อปปิ้งแชนแนลจากโบนาชีได้ในโอกาสหน้า แล้วเจอกันใหม่นะ!",
  ui_story_5004_50041202_42_dialog_content = "นี่ไม่ใช่เวลามาดูโฆษณานะ!",
  ui_story_5004_50041202_43_dialog_content = "เหลือแค่ฉันกับสโมกกี้แล้วเหรอเนี่ย??",
  ui_story_5004_50041202_44_dialog_content = "นี่ เลิกอู้ได้แล้ว หาทางทำอะไรซักอย่างสิ!",
  ui_story_5004_50041202_45_dialog_content = "หา? พูดเป็นเล่นน่า? นึกว่าพวกนายจะมีประโยชน์กว่านี้ซะอีกนะเนี่ย",
  ui_story_5004_50041202_46_dialog_content = "ที่ไหนได้ มีแต่พวกไร้ประโยชน์",
  ui_story_5004_50041202_47_dialog_content = "แต่พวกเขาก็บล็อกลูกให้คุณตั้งเยอะนะ!",
  ui_story_5004_50041202_48_dialog_content = "ถ้าไม่ได้พวกเขา ป่านนี้คุณก็โดนออกไปนานแล้ว!",
  ui_story_5004_50041202_49_dialog_content = "จะยอมแพ้ตอนนี้แล้วให้การเสียสละของพวกเขาสูญเปล่างั้นเหรอ?",
  ui_story_5004_50041202_50_dialog_content = "โอเค ก็ได้ ก็ได้ แต่ที่ผ่านมานายก็เอาแต่ยืนเฉย ๆ เหมือนกันไม่ใช่หรือไง?",
  ui_story_5004_50041202_51_dialog_content = "เอาเถอะ ฉันไม่อยากติดหนี้พวกนายหรอก",
  ui_story_5004_50041202_52_dialog_content = "อยู่เฉย ๆ แล้วดูให้ดีล่ะ อย่าลืมพากย์ท่าไม้ตายสุดเท่ให้ฉันด้วยนะ!",
  ui_story_5004_50041202_53_dialog_content = "พากย์เหรอ? ได้เลย! ถ้ามันทำให้คุณแตะลูกได้ ผมยอมทุกอย่าง!",
  ui_story_5004_50041202_54_dialog_content = "โอเค! รับปากแล้วนะ!",
  ui_story_5004_50041202_55_dialog_content = "นี่...",
  ui_story_5004_50041202_56_dialog_content = "เจเนวีฟ",
  ui_story_5004_50041202_57_dialog_content = "อะไร? พร้อมยอมรับความพ่ายแพ้แล้วใช่มั้ย?",
  ui_story_5004_50041202_58_dialog_content = "ถามหน่อยสิ นี่เธอแคร์เรื่องเอาชนะคนอื่นขนาดนี้เลยเหรอ?",
  ui_story_5004_50041202_59_dialog_content = "แน่นอนอยู่แล้ว! เพื่อศักดิ์ศรีของตระกูลและตัวฉันเอง ฉันจะแพ้ใครไม่ได้เด็ดขาด โดยเฉพาะเธอ!",
  ui_story_5004_50041202_60_dialog_content = "เธอช่วงชิงเกียรติยศไปจากฉัน แล้วหลายปีที่ผ่านมาฉันก็ตามหาเธอมาตลอด",
  ui_story_5004_50041202_61_dialog_content = "เพื่อที่ซักวันนึง ฉันจะได้บดขยี้เธอจนหมดรูป ให้เธอได้เจ็บปวดและเสียใจในความผิดของตัวเอง!",
  ui_story_5004_50041202_62_dialog_content = "...งั้นแย่หน่อยนะ",
  ui_story_5004_50041202_63_dialog_content = "หา?",
  ui_story_5004_50041202_64_dialog_content = "เพราะฉันก็เกลียดการพ่ายแพ้เหมือนกัน!",
  ui_story_5004_50041202_65_dialog_content = "แสดงฝีมือของเธอมา!",
  ui_story_5004_50041202_66_dialog_content = "มาดูกันว่าเธอจะชนะฉันได้มั้ย!",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>ลูกตบ☆ซูเปอร์เพลิงนรก☆สังหาร!</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "!!!",
  ui_story_5004_50041202_69_dialog_content = "นี่มัน! ราวกับว่าเพลิงนรกกำลังปกคลุมลูกวอลเลย์ แล้วมันก็แหวกอากาศพุ่งเข้าไปหาเจเนวีฟ!",
  ui_story_5004_50041202_70_dialog_content = "(เอ๊ะ แล้วฉันก็พากย์ออกไปจริง ๆ ด้วยนะ... น่าขายหน้าชะมัด!)",
  ui_story_5004_50041202_71_dialog_content = "เจเนวีฟ!",
  ui_story_5004_50041202_72_dialog_content = "แฟน ๆ ของเจเนวีฟล้อมวงเข้ามาปกป้องเธอ นั่นจะได้ผลรึเปล่า?",
  ui_story_5004_50041202_73_dialog_content = "ลูกวอลเลย์พุ่งใส่ฝูงชนราวกับอุกกาบาต!!",
  ui_story_5004_50041202_74_dialog_content = "เจเนวีฟกับแฟน ๆ ผู้น่าสงสารกระเด็นออกนอกสนามไปแล้ว! แถมบนสนามยังเกิดรูขนาดใหญ่ทิ้งเอาไว้!",
  ui_story_5004_50041202_75_dialog_content = "และผู้ชนะก็คือ... ทีม PlayerName!",
  ui_story_5004_50041202_76_dialog_content = "สโมกกี้ชี้นิ้วขึ้นฟ้า เป็นท่าโพสประกาศชัยชนะประจำตัวสินะ! เป็นลูกตบที่ยอดจริง ๆ!",
  ui_story_5004_50041202_77_dialog_content = "นายพากย์ใช้ได้เหมือนกันนะ อย่างน้อยก็อธิบายความยิ่งใหญ่ของฉันได้เกือบครึ่ง ไม่เลว",
  ui_story_5004_50041202_78_dialog_content = "ขอบคุณครับ... แต่นั่นมันควรเป็นหน้าที่ของคนที่ไม่ได้แข่งไม่ใช่เรอะ??",
  ui_story_5004_50041202_79_dialog_content = "ช่างเถอะ เมื่อกี้นี้ยอดไปเลย! คุณจัดการทุกคนด้วยลูกตบแค่ลูกเดียว!",
  ui_story_5004_50041202_80_dialog_content = "(เธอเป็นสัตว์ประหลาดชัด ๆ! อยู่ ๆ ก็รู้สึกเห็นใจเจเนวีฟขึ้นมาเลยแฮะ)",
  ui_story_5004_50041301_1_dialog_content = "เฮ้อ... เหนื่อยชะมัด",
  ui_story_5004_50041301_2_dialog_content = "ถึงฉันจะไม่ได้ทำอะไร แต่แค่หลบบอลก็หมดแรงแล้ว...",
  ui_story_5004_50041301_3_dialog_content = "ไม่นึกเลยว่าการแข่งมันจะดุเดือดขนาดนี้ นี่แค่วันแรกเองนะ",
  ui_story_5004_50041301_4_dialog_content = "เจเนวีฟแข็งแกร่งมาก ๆ ก็จริง แต่สโมกกี้นี่คนละระดับกันเลย",
  ui_story_5004_50041301_5_dialog_content = "ว่าแต่สองคนนั้นทะเลาะกันเรื่องอะไรนะ?",
  ui_story_5004_50041301_6_dialog_content = "หลังจากนั้นเบริลกับราฟาเอลก็ไปตกปลา ดูท่าทั้งสองคนจะสนุกมาก ๆ",
  ui_story_5004_50041301_7_dialog_content = "ถึงเบริลจะดูเหนื่อย ๆ แต่มีราฟาเอลคอยดูแลก็คงไม่เป็นไร",
  ui_story_5004_50041301_8_dialog_content = "โอ๊ะ ฉันต้องไปขอบคุณไวซ์ที่บังลูกให้ฉัน",
  ui_story_5004_50041301_9_dialog_content = "ถ้าไม่ได้เธอ ป่านนี้ฉันคงเข้า ICU ไปแล้ว",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก</color>",
  ui_story_5004_50041301_11_dialog_content = "PlayerName นอนรึยังน่ะ?",
  ui_story_5004_50041301_12_dialog_content = "มาแล้ว",
  ui_story_5004_50041301_13_dialog_content = "มีอะไรเหรอ คาร์ลีน?",
  ui_story_5004_50041301_14_dialog_content = "แค่แวะมาถามน่ะ ว่านายนอนรึยัง PlayerName",
  ui_story_5004_50041301_15_dialog_content = "ฉันไม่ได้มีโอกาสมาเที่ยวทะเลบ่อย ๆ ก็เลยไม่อยากหมกตัวอยู่ในห้องทั้งคืนน่ะ",
