  ui_story_5004_50041301_23_dialog_content = "หืม? ว่าไง!",
  ui_story_5004_50041301_24_dialog_content = "เรื่องอวิดัซกับชูมเมอร์... ฉันอยากจะขอบคุณนายให้เป็นเรื่องเป็นราวซักที",
