  ui_story_5004_50041301_30_dialog_content = "ครั้งแรกที่เจอนาย ใจฉันมีแต่อคติ แล้วก็ไม่เชื่อว่านายจะอยู่อย่างโดดเดี่ยวมาเป็นสิบปี...",
