  ui_story_5004_50041301_32_dialog_content = "เมื่อเผชิญกับอันตราย นายก็พิสูจน์ตัวเองครั้งแล้วครั้งเล่าด้วยความสามารถอันยอดเยี่ยม ทักษะการสั่งการของนายไม่ธรรมดาเลย",
  ui_story_5004_50041301_33_dialog_content = "ถึงนายจะต่อสู้กับอิคลิพไซท์ไม่ได้ แต่ก็เผชิญหน้าพวกมันอย่างไม่หวาดกลัวทุกครั้ง",
  ui_story_5004_50041301_34_dialog_content = "...",
