  ui_story_5004_50041301_36_dialog_content = "การเสียสละตัวเองเพื่อช่วยเหลือผู้อื่นนั้นเป็นสิ่งที่ดี บางครั้งนายยินดีเสี่ยงชีวิตตนเองด้วยซ้ำ นี่เป็นสิ่งที่น่าชื่นชมมาก ๆ",
