  ui_story_5004_50041501_16_dialog_content = "นิ้วแรกจะเริ่มใน 30, 29...",
  ui_story_5004_50041501_17_dialog_content = "อย่านะ ปล่อยผมไปเถอะ! ผมแค่มาส่งของเท่านั้น!",
  ui_story_5004_50041501_18_dialog_content = "ผมไม่ใช่คนเลวซักหน่อย! แม่นั่นแต่งตัวโป๊เองต่างหากล่ะ!",
