  ui_story_5004_50041501_20_dialog_content = "10, 9, 8...",
  ui_story_5004_50041501_21_dialog_content = "ผมสารภาพทุกอย่างแล้ว! จะเอาอะไรอีก?",
  ui_story_5004_50041501_22_dialog_content = "กร๊อบ กร๊อบ",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>อ๊ากก! มือฉัน!</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "นังบ้าเอ๊ย หักทีละสองนิ้วเลยเหรอ! เป็นบ้าอะไรเนี่ย?!",
  ui_story_5004_50041501_25_dialog_content = "ยัยผู้หญิงโรคจิต! โอ๊ยย!",
  ui_story_5004_50041501_26_dialog_content = "หนึ่งนิ้วเพราะหมดเวลา ส่วนอีกนิ้วเพราะว่าแกโกหก",
  ui_story_5004_50041501_27_dialog_content = "ฉันแค่มา... ส่งของจริง ๆ บ้าเอ๊ย...",
  ui_story_5004_50041501_28_dialog_content = "งั้นก็เอาของนั่นมา",
  ui_story_5004_50041501_29_dialog_content = "ไม่ได้!",
  ui_story_5004_50041501_30_dialog_content = "มั่นใจขนาดนั้นเลยเหรอ? ถ้างั้นนิ้วที่สามจะไปในอีก... 5, 4...",
