  ui_story_5004_50041501_32_dialog_content = "ศูนย์",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>อ๊ากกก!</anim></size> แฮ่ก...",
  ui_story_5004_50041501_34_dialog_content = "แล้วคิดว่าฉันจะปล่อยแกไปหรือไง?",
  ui_story_5004_50041501_35_dialog_content = "จะตายตอนนี้หรือตายวันหลัง เลือกมา",
  ui_story_5004_50041501_36_dialog_content = "ก็ได้ ก็ได้ ปล่อยฉันเถอะ!",
  ui_story_5004_50041501_37_dialog_content = "เอ้า อยากได้อะไรเอาไปเลย ยัยโรคจิต!!",
  ui_story_5004_50041501_38_dialog_content = "แค่จดหมายฉบับเดียวเนี่ยนะ? ข้างในมีอะไร?",
  ui_story_5004_50041501_39_dialog_content = "คืนฉันมาเถอะ นี่มันของคนใหญ่คนโตนะ ถ้าเธอเอาไป พวกเราทั้งคู่ไม่รอดแน่!",
  ui_story_5004_50041501_40_dialog_content = "สายไปแล้ว",
  ui_story_5004_50041501_41_dialog_content = "ตอนนี้ฉันอยากรู้แล้วสิ ว่าข้างในมีอะไร",
  ui_story_5004_50041501_42_dialog_content = "หาดบันไดสวรรค์? ที่ไหนน่ะ?",
  ui_story_5004_50041501_43_dialog_content = "นี่มันแผนที่ขุมทรัพย์เหรอ?",
  ui_story_5004_50041501_44_dialog_content = "เธออ่านแล้วเหรอ?! พวกเราไม่รอดแน่!",
  ui_story_5004_50041501_45_dialog_content = "<size=45>ฉันถามแกอยู่นะ!</size>",
  ui_story_5004_50041501_46_dialog_content = "ฉันก็ไม่รู้ รู้แค่ว่ามันอันตรายมาก ๆ!",
  ui_story_5004_50041501_47_dialog_content = "เหมือนพวกนั้นจะเตรียมพิธีเรียกภัยพิบัติมาทำลายโลก!",
  ui_story_5004_50041501_48_dialog_content = "ขอคืนเถอะนะ ฉันไม่อยากมีเรื่อง!",
  ui_story_5004_50041501_49_dialog_content = "เอ่อ เมื่อกี้หัวไม่ได้กระแทกอะไรใช่มั้ย?",
  ui_story_5004_50041501_50_dialog_content = "พูดเพ้อเจ้ออะไรของแกน่ะ?",
  ui_story_5004_50041501_51_dialog_content = "ยิ่งพูดฉันก็ยิ่งอยากรู้แฮะ",
  ui_story_5004_50041501_52_dialog_content = "ตัดสินใจแล้ว! งั้นฉันไปดูด้วยตาตัวเองดีกว่า!",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>เหมือนกับที่จดหมายบอกไว้...</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>สิ่งที่ข้าตามหา คือกำแพงแห่งเสียงทอดถอนใจทั้งสาม</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>สิ่งที่ข้าต้องการ คือการกำเนิดใหม่จากเถ้าถ่าน</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>ฝนโลหิตโปรยปรายเมื่อดวงตะวันโผล่พ้นขอบฟ้ายามรุ่งสาง</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>เสียงร่ำไห้โหยหวนฉาบทาอาทิตย์อัสดงยามสนธยา</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>เมื่อวินาทีแห่งการพิพากษามาถึง ณ ปลายทางของวันเวลา</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>องค์ราชันจักตื่นขึ้นจากนิทราในที่สุด</color>",
  ui_story_5004_50041501_60_dialog_content = "เพ้อเจ้ออะไรเนี่ย? ปริศนางั้นเหรอ?",
  ui_story_5004_50041501_61_dialog_content = "อย่าบอกนะว่าสุดท้ายก็เสียเวลาเปล่า...",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก</color>",
  ui_story_5004_50041501_63_dialog_content = "เข้ามา",
  ui_story_5004_50041501_64_dialog_content = "สวัสดี คุณสโมกกี้ แมนติคอร์ จากอัมบราตันสินะ?",
  ui_story_5004_50041501_65_dialog_content = "เธอรู้จักฉันด้วยเหรอ?",
  ui_story_5004_50041501_66_dialog_content = "แน่นอน ฉันรู้ว่าคุณเป็นใคร มาที่นี่เพื่ออะไร แล้วก็รู้ด้วยว่าจดหมายนั่นไม่ใช่ของของคุณ",
  ui_story_5004_50041501_67_dialog_content = "อยากได้อะไรจากฉันกันล่ะ",
  ui_story_5004_50041501_68_dialog_content = "ฮ่าฮ่าฮ่า!",
  ui_story_5004_50041501_69_dialog_content = "...?",
  ui_story_5004_50041501_70_dialog_content = "ขอโทษนะ มันตลกดีน่ะ",
  ui_story_5004_50041501_71_dialog_content = "ฉันไม่อยากได้อะไรจากคุณหรอก ในฐานะที่ัฉันเป็นผู้จัดงานราชันเจ้าสมุทร ก็แค่อยากจะชวนให้คุณมาลงแข่ง",
  ui_story_5004_50041501_72_dialog_content = "แค่นั้นเองเหรอ?",
  ui_story_5004_50041501_73_dialog_content = "ใช่",
  ui_story_5004_50041501_74_dialog_content = "เธอเป็นคนของทรู ออเดอร์ ฉันไม่เชื่อเธอหรอก",
  ui_story_5004_50041501_75_dialog_content = "ถึงจะอยู่กับทรู ออเดอร์ แต่ฉันก็มีสิทธิ์จัดงานไม่ใช่หรือไง?",
  ui_story_5004_50041501_76_dialog_content = "วัตถุนิยมยังไงก็ยังเป็นรากฐานสำคัญในการแสวงหาสัจธรรม แล้วงานนี้ก็ได้หลายตังค์ซะด้วย",
  ui_story_5004_50041501_77_dialog_content = "เอาล่ะ คุณอยากลงแข่งมั้ยล่ะ? รางวัลชนะเลิศอาจจะมีสิ่งที่คุณตามหาก็ได้นะ",
  ui_story_5004_50041501_78_dialog_content = "แล้วถึงคุณจะแพ้...",
  ui_story_5004_50041501_79_dialog_content = "พอเลยนะ ฉันไม่มีทางแพ้อยู่แล้ว แล้วฉันก็ไม่สนด้วยว่าแพ้แล้วจะเกิดอะไรขึ้น",
  ui_story_5004_50041501_80_dialog_content = "คนส่งของนั่นเป็นคนของเธอเหรอ?",
  ui_story_5004_50041501_81_dialog_content = "ฉันจะไปรู้ได้ไงล่ะ?",
  ui_story_5004_50041501_82_dialog_content = "ฉันถ่อมาถึงนี่แล้วนะ อธิบายให้เคลียร์ ๆ เถอะน่า",
  ui_story_5004_50041501_83_dialog_content = "ฉันอยากรู้ว่าเธอแอบวางแผนอะไรอยู่กันแน่",
  ui_story_5004_50041601_1_dialog_content = "อาการของเบริลเกิดจากลูมินาที่ไม่เสถียรงั้นเหรอ?",
  ui_story_5004_50041601_2_dialog_content = "ใช่ เมื่อไม่กี่วันฉันพึ่งคุยกับเบเร็ตตา แล้วเธอก็เจอเคสคล้าย ๆ กัน",
  ui_story_5004_50041601_3_dialog_content = "แล้วยังมีเรื่องแฟ้มข้อมูลของตระกูลกอทิเยร์อีก...",
  ui_story_5004_50041601_4_dialog_content = "แต่นั่นเป็นเอกสารลับที่มีแค่ท่านเจ้าเมืองกับคนไม่กี่คนที่อ่านได้",
  ui_story_5004_50041601_5_dialog_content = "เบริลเป็นคนจากตระกูลกอทิเยร์งั้นเหรอ?",
  ui_story_5004_50041601_6_dialog_content = "ใช่! ตอนเราคุยกันเมื่อคืน เธอก็พูดถึงครอบครัวตัวเองให้ฟัง แล้วก็พูดถึงตระกูลอื่นด้วย...",
  ui_story_5004_50041601_7_dialog_content = "ตระกูลไพรัส อะไรนี่แหละ... ฉันจำไม่ได้แล้ว",
  ui_story_5004_50041601_8_dialog_content = "ไม่เป็นไร ว่าแต่ พวกเธอสองคนสนิทกันดีนะเนี่ย",
  ui_story_5004_50041601_9_dialog_content = "แน่นอน เราคุยกันทุกเรื่องเลย! แล้วเบริลก็คุยเก่งกว่าที่นายคิดอีกนะ!",
  ui_story_5004_50041601_10_dialog_content = "งั้นเหรอ ดีแล้วล่ะ ต่อไปคงต้องรบกวนเธออีกเยอะเลย",
  ui_story_5004_50041601_11_dialog_content = "ไม่มีปัญหา! เดี๋ยวฉันเอาเรื่องนี้ไปปรึกษาคาร์ลีนก็แล้วกัน เผื่อจะมีทางทำอะไรได้บ้าง!",
  ui_story_5004_50041601_12_dialog_content = "ฉันกลับไปหาเบริลก่อนนะ! แล้วเจอกันในงาน!",
  ui_story_5004_50041601_13_dialog_content = "อื้ม ระวังตัวด้วยนะ",
  ui_story_5004_50041601_14_dialog_content = "โอ๊ย!",
  ui_story_5004_50041601_15_dialog_content = "เป็นอะไรรึเปล่า?",
  ui_story_5004_50041601_16_dialog_content = "ไม่เป็นไร โทษทีนะ!",
  ui_story_5004_50041601_17_dialog_content = "สโมกกี้?",
  ui_story_5004_50041601_18_dialog_content = "นายคือ PlayerName ใช่มั้ย? ฉันอยากจะมาแนะนำตัวอย่างเป็นทางการน่ะ",
