  ui_story_5004_50041601_21_dialog_content = "...",
  ui_story_5004_50041601_22_dialog_content = "เท่านี้เหรอ?",
  ui_story_5004_50041601_23_dialog_content = "ใช่",
  ui_story_5004_50041601_24_dialog_content = "แล้ว สโมกกี้ คุณมีธุระอะไรเหรอ?",
  ui_story_5004_50041601_25_dialog_content = "ในเมื่อเราอยู่ทีมเดียวกัน ฉันก็คิดว่าเราควรรู้จักกันไว้",
  ui_story_5004_50041601_26_dialog_content = "ดูจากแมตช์ที่แล้ว ถ้าคิดแต่จะพึ่งฉันอย่างเดียว ฉันว่าต่อไปจะต้องมีปัญหาแน่",
  ui_story_5004_50041601_27_dialog_content = "(จริงเหรอ?)",
  ui_story_5004_50041601_28_dialog_content = "นั่นแหละ ฉันเลยคิดว่าญาติดีกับทุกคนไว้มันก็ไม่เสียหาย",
