  ui_story_5004_50041601_33_dialog_content = "อืม... ฉันรู้อยู่แล้วล่ะว่านายต้องถาม",
  ui_story_5004_50041601_34_dialog_content = "แต่ก็ไม่รู้ว่านายจะพอใจกับคำตอบของฉันรึเปล่านะ",
  ui_story_5004_50041601_35_dialog_content = "เราเกิดที่เมืองเพเทียเบิร์กเหมือนกัน ฉันเป็นคนจากตระกูลแมนติคอร์ ส่วนเธอเป็นคนตระกูลวรอนสกี้",
  ui_story_5004_50041601_36_dialog_content = "จะพูดยังไงดีล่ะ... ทั้งสองตระกูลเป็นคู่แข่งกันมาตลอด แต่ถึงอย่างนั้น ตอนเด็ก ๆ พวกเราก็เป็นเพื่อนสนิทกัน",
  ui_story_5004_50041601_37_dialog_content = "ตอนนั้นเธอน่ารักอยู่นะ คอยตามฉันต้อย ๆ เลย ดีกว่าตอนนี้เยอะ",
  ui_story_5004_50041601_38_dialog_content = "ที่มันเกิดเรื่องขึ้น คงเพราะตอนนั้นฉันยังเป็นเด็กต่อต้านสังคม แล้วก็ชอบหาความตื่นเต้น",
  ui_story_5004_50041601_39_dialog_content = "ในการทดสอบของเจเนวีฟ ฉันเผลอแสดงฝีมือเพลินไปหน่อย",
  ui_story_5004_50041601_X39_dialog_content = "นั่นทำให้กรรมการเลือกฉันแทนที่จะเลือกเจเนวีฟ แล้วก็ทำให้ตระกูลของเธอหมดโอกาสเป็นขุนนางระดับสูงในลูโมโพลิส",
  ui_story_5004_50041601_40_dialog_content = "เรื่องนั้นทำให้ตัวเธอกับตระกูลต้องเสื่อมเสียเกียรติ",
  ui_story_5004_50041601_41_dialog_content = "ฉันก็แค่หาอะไรสนุก ๆ ทำ ใครจะไปรู้ว่าพวกนั้นเปราะบางขนาดนั้นกันล่ะ?",
  ui_story_5004_50041601_42_dialog_content = "ตั้งแต่ตอนนั้นฉันก็เลยหนีออกจากบ้าน เพราะชนชั้นสูงน่ะคอยแต่หาเรื่องน่ารำคาญมาให้",
