  ui_story_5004_50041701_1_dialog_content = "ฟู่...",
  ui_story_5004_50041701_2_dialog_content = "ตื่นเต้นเหรอ PlayerName?",
  ui_story_5004_50041701_3_dialog_content = "ก็นิดหน่อย...",
