  ui_story_5004_50041701_5_dialog_content = "ฉันว่าสำนวนนั่นมันคือ <color=#FFB400>ทหารบุกมาใช้ขุนพลต้านรับ สายน้ำถาโถมใช้ดินต้านทาน</color> มากกว่านะ",
  ui_story_5004_50041701_6_dialog_content = "นั่นแหละ นั่นแหละ สงสัยผู้บัญชาการฮิอิโระต้องเคยหลงทางในทะเลทรายเรดีเซลแน่ ๆ เลย...",
  ui_story_5004_50041701_7_dialog_content = "(ถ้าคุณฮิอิโระได้ยินเข้า คงให้เธอคัดลายมือ 100 จบแหง ๆ!)",
  ui_story_5004_50041701_8_dialog_content = "วันนี้ฉันพกหอกดักแด้จันทรามาด้วย เรื่องออกแรงให้เป็นหน้าที่ฉันเอง",
