  ui_story_5004_50041701_119_dialog_content = "ยังไงก็เถอะ PlayerName ถ้ามัวแต่พึ่งพาคนอื่นให้อ่าน \"คู่มือการต่อสู้\" แทน นายก็จะไม่พัฒนานะ...",
  ui_story_5004_50041701_120_dialog_content = "อยู่ ๆ ก็เปลี่ยนจากการแข่งขันซีเรียสกลายเป็นเกมเฮฮาหน้าร้อนแบบนี้ ยังไงฉันก็ปรับอารมณ์ไม่ทันหรอก!",
