  ui_story_5004_50041701_129_dialog_content = "อึก!",
  ui_story_5004_50041701_130_dialog_content = "คิดอะไรสักอย่างสิ สโมกกี้!",
  ui_story_5004_50041701_131_dialog_content = "คงถึงเวลาต้องเอาจริงแล้วสินะ!",
  ui_story_5004_50041701_132_dialog_content = "เดี๋ยวนะ คุณไปเอา<color=#FFB400>ปืนฉีดน้ำกระบอกยักษ์แบบจัดเต็ม</color>มาจากไหนเนี่ย?!",
  ui_story_5004_50041701_133_dialog_content = "คิดว่าแค่คนเยอะกว่าแล้วจะชนะหรือไง!",
  ui_story_5004_50041701_134_dialog_content = "หนอย! ทุกคน! ปกป้องคุณเจเนวีฟอย่างสุดกำลัง!",
  ui_story_5004_50041701_135_dialog_content = "ไม่ไหวแล้ว หัวหน้า...",
  ui_story_5004_50041701_136_dialog_content = "อ๊าก!",
