  ui_story_5004_50041701_136X2_dialog_content = "ฉันจะไม่ปรานีแล้วนะ!",
  ui_story_5004_50041701_136X3_dialog_content = "หวา มองไม่เห็นอะไรเลย!",
  ui_story_5004_50041701_136X4_dialog_content = "ถอยไป ไวซ์ เดี๋ยวฉันคุ้มกันให้",
  ui_story_5004_50041701_136X5_dialog_content = "ฉันจะแสดงพลังของ \"โรสฮันเตอร์\" ในมือให้เธอได้เห็น!",
  ui_story_5004_50041701_136X6_dialog_content = "ฮึบ!",
  ui_story_5004_50041701_136X7_dialog_content = "โอ๊ย ฉันก็มองไม่เห็นเหมือนกัน",
  ui_story_5004_50041701_136X8_dialog_content = "เราไม่ได้อยู่ใต้ทะเลนะ เธอทำได้! คาร์ลีน!",
  ui_story_5004_50041701_136X9_dialog_content = "พวกเธอเป็นผู้ใช้ลูมินาติกส์ธาตุน้ำไม่ใช่เหรอ? ทำไมแพ้ปืนฉีดน้ำง่าย ๆ แบบนั้นล่ะ?",
  ui_story_5004_50041701_136X10_dialog_content = "ฮ่าฮ่าฮ่า! ถ้าไม่อยากตัวเปียกชุ่มก็ยอมแพ้ซะ!",
