  ui_story_5004_50041701_136X12_dialog_content = "สโมกกี้? ว่าแล้วเชียวว่าแฟน ๆ ของฉันคงยันเธอไม่ได้นาน",
  ui_story_5004_50041701_136X13_dialog_content = "ทุกคน เล็งสโมกกี้เอาไว้ ฉันจะจัดการสองคนนั้นเอง!",
  ui_story_5004_50041701_138_dialog_content = "ได้เลย คุณเจเนวีฟ!",
  ui_story_5004_50041701_139_dialog_content = "ลุย ลุย ลุย!",
  ui_story_5004_50041701_140_dialog_content = "ชิ ปืนฉีดน้ำมันแรงจนฉันเล็งไม่ได้เลย!",
  ui_story_5004_50041701_141_dialog_content = "พวกนั้นสกัดสโมกกี้ได้แล้ว! ทำอะไรซักอย่างสิ บร็อค!",
  ui_story_5004_50041701_142_dialog_content = "ฉันจะทำอะไรได้ล่ะ? ขนาดนายยังไม่อ่านกติกาเลย แล้วฉันจะเหลือเรอะ?",
  ui_story_5004_50041701_143_dialog_content = "ฉันไม่ได้เตรียมอะไรมาซักอย่าง จะให้ใช้กำปั้นซัดหน้าพวกนั้นหรือไง?",
  ui_story_5004_50041701_144_dialog_content = "บร็อค PlayerName! ดูสิว่าฉันเจออะไรในกระเป๋า?",
  ui_story_5004_50041701_145_dialog_content = "ฉันมี<color=#FFB400>เต็นท์สนาม</color>กันน้ำด้วยล่ะ! อยากเข้ามาหลบก่อนมั้ย?",
  ui_story_5004_50041701_146_dialog_content = "ใครมันอยากจะเบียดกับนายในเต็นท์กันหา!",
  ui_story_5004_50041701_147_dialog_content = "เสียงน้ำกระทบเต็นท์มันก็เหมือนเสียงฝนนั่นแหละ มันยอดมากเลยนะ",
  ui_story_5004_50041701_148_dialog_content = "แล้วฉันก็มี<color=#FFB400>เก้าอี้กลางแจ้ง</color>ด้วย อยากนั่งก่อนมั้ง?",
  ui_story_5004_50041701_149_dialog_content = "ไม่!",
  ui_story_5004_50041701_150_dialog_content = "เฮ้ย! มันใช่เวลามาปิกนิกมั้ยเนี่ย!",
  ui_story_5004_50041701_151_dialog_content = "ชื่อบร็อคใช่มั้ย?",
  ui_story_5004_50041701_152_dialog_content = "ใช่ มีอะไร!",
  ui_story_5004_50041701_153_dialog_content = "ฉันจะเปิดทางให้ เดี๋ยวนายขว้าง PlayerName ไปตรงกลางสนามให้หมอนั่นขุดหาตัวหมากรุกนะ!",
