  ui_story_5004_50041701_168_dialog_content = "ฟื้นสิ PlayerName",
  ui_story_5004_50041701_169_dialog_content = "บร็อค?!",
  ui_story_5004_50041701_170_dialog_content = "เราเป็นฝ่ายชนะ บร็อคโยนนายฝ่าม่านน้ำของแฟนคลับ หัวนายปักเข้ากับทราย แล้วตัวหมากรุกก็อยู่ในนั้นพอดี... ในเมื่อนายเป็นคนเจอ เราก็เลยชนะ",
  ui_story_5004_50041701_171_dialog_content = "จากนั้นนายก็สลบไป แต่แฟน ๆ ของเจเนวีฟสติแตกก็เลยรุมยิงนายจนเกือบจะจมน้ำ โชคดีที่เจเนวีฟสั่งให้หยุดทัน",
  ui_story_5004_50041701_172_dialog_content = "โทษทีนะ ที่นี่มีเจ้าหน้าที่รักษาความปลอดภัยอย่างบร็อคคนเดียวที่ผ่านการฝึกผายปอด ก็เลย...",
