  ui_story_5004_50041901_3_dialog_content = "หน้าที่กอบกู้ตระกูลวรอนสกี้อยู่ที่ลูกแล้ว",
  ui_story_5004_50041901_4_dialog_content = "...",
  ui_story_5004_50041901_5_dialog_content = "ลูกจะต้องฝึกฝนให้หนัก ถึงจะยังเด็กก็ตาม",
