  ui_story_5004_50041901_8_dialog_content = "อาจารย์ท่านนี้จะมาสอนลูมินาติกส์และมารยาทสังคมให้ลูก เธอเป็นอดีตขุนนางผู้มีชื่อเสียงในลูโมโพลิส",
