  ui_story_5004_50041901_11_dialog_content = "ลูกจะต้องชนะลูกสาวตระกูลแมนติคอร์ได้แน่",
  ui_story_5004_50041901_12_dialog_content = "เจเนวีฟ? เจเนวีฟ?",
