  ui_story_5004_50041901_15_dialog_content = "หนูอยากทำการบ้านให้เสร็จเร็ว ๆ น่ะค่ะ เมื่อคืนเลยอยู่ดึกนิดหน่อย",
  ui_story_5004_50041901_16_dialog_content = "นั่นมันการบ้านของทั้งสัปดาห์เลยนะ ไม่เห็นจะต้องฝืนขนาดนั้นเลยนี่นา",
  ui_story_5004_50041901_17_dialog_content = "...",
  ui_story_5004_50041901_18_dialog_content = "โตขึ้นเธออยากทำอะไรเหรอ เจเนวีฟ?",
  ui_story_5004_50041901_19_dialog_content = "ก็ คงรักษาเกียรติยศของตระกูลมั้งคะ?",
