  ui_story_5004_50041901_21_dialog_content = "ไม่รู้สิคะ หนูก็ไม่แน่ใจเหมือนกัน หนูอาจจะไม่เคยคิดถึงมันเลยก็ได้",
  ui_story_5004_50041901_22_dialog_content = "งั้นรึ ถ้าอย่างนั้นเราคุยเรื่องอื่นกันเถอะ",
  ui_story_5004_50041901_23_dialog_content = "สัปดาห์ที่แล้วเธอไปเจอกับเด็กสาวตระกูลแมนติคอร์คนนั้นมาใช่มั้ย เจเนวีฟ?",
  ui_story_5004_50041901_24_dialog_content = "ครูรู้ได้ยังไงน่ะ?",
  ui_story_5004_50041901_25_dialog_content = "ไม่เป็นไร ครูไม่บอกใครหรอก",
  ui_story_5004_50041901_26_dialog_content = "ขอบคุณค่ะ",
  ui_story_5004_50041901_27_dialog_content = "แต่ทำไม...",
  ui_story_5004_50041901_28_dialog_content = "ช่างเถอะ ฉันไม่ควรละลาบละล้วงเรื่องส่วนตัวของเธอ",
  ui_story_5004_50041901_29_dialog_content = "...",
  ui_story_5004_50041901_30_dialog_content = "เจเนวีฟ ครูคิดว่าเธออย่าคิดมากเรื่องเกียรติยศของตระกูลจะดีกว่า",
  ui_story_5004_50041901_31_dialog_content = "ทำไมล่ะคะ?",
  ui_story_5004_50041901_32_dialog_content = "เธอรู้รึเปล่าล่ะ ว่าทำไมครูถึงทิ้งสถานะชนชั้นสูงไป?",
  ui_story_5004_50041901_33_dialog_content = "ขอบคุณที่อุตส่าห์สอนลูกของผมมาตลอดหลายปีนะครับ ขอบคุณสำหรับทุกอย่างจริง ๆ",
  ui_story_5004_50041901_34_dialog_content = "ไม่ต้องให้เป็นพิธีรีตองขนาดนั้นหรอกค่ะ เจเนวีฟเองก็มีพรสวรรค์และเป็นเด็กขยันอยู่แล้ว",
  ui_story_5004_50041901_35_dialog_content = "พลังเวทมนตร์พิธีกรรมของเธอในตอนนี้แข็งแกร่งกว่าชนชั้นสูงส่วนใหญ่อยู่มากเลยทีเดียว",
  ui_story_5004_50041901_36_dialog_content = "เพราะฉะนั้น ฉันเองก็ไม่มีอะไรจะสอนเธออีกแล้ว",
  ui_story_5004_50041901_37_dialog_content = "แล้วจากนี้ไปครูจะทำอะไรต่อเหรอคะ?",
  ui_story_5004_50041901_38_dialog_content = "ฉันก็คงต้องตอบเหมือนเธอนะ ว่าไม่รู้เหมือนกัน อาจจะออกไปค้นหาอะไรบางอย่าง หรือไม่ก็ใครซักคน",
  ui_story_5004_50041901_39_dialog_content = "ใครจะรู้ล่ะ การเดินทางมันก็อาจจะมีคุณค่าในตัวมันเองก็ได้",
  ui_story_5004_50041901_40_dialog_content = "ลาก่อน เจเนวีฟ",
  ui_story_5004_50041901_41_dialog_content = "ว่าไงนะ อิคลิพไซท์บุกมาประชิดเมืองงั้นเหรอ?",
  ui_story_5004_50041901_42_dialog_content = "เรามีกำลังพลป้องกันเพเทียเบิร์กไม่พอซะด้วย ต้องขอความช่วยเหลือจากลูโมโพลิส",
  ui_story_5004_50041901_43_dialog_content = "ตระกูลซาลาร์สจากลูโมโพลิสตกลงว่าจะช่วยเรา แต่มีเงื่อนไขก็คือ...",
  ui_story_5004_50041901_44_dialog_content = "พวกเขาอยากตรวจสอบเวทมนตร์พิธีกรรมของเจเนวีฟ และอาจจะรับเธอไปอุปการะเป็นลูกบุญธรรม",
  ui_story_5004_50041901_45_dialog_content = "ถ้าได้สานสัมพันธ์กับตระกูลที่มีอำนาจขนาดนั้น มันก็จะเป็นผลดีกับตระกูลวรอนสกี้ของเรามาก ๆ",
  ui_story_5004_50041901_46_dialog_content = "เจเนวีฟ",
  ui_story_5004_50041901_47_dialog_content = "เข้าใจแล้วค่ะ คุณพ่อ",
  ui_story_5004_50041901_48_dialog_content = "เธอนี่แข็งแกร่งจริง ๆ เจเนวีฟ",
  ui_story_5004_50041901_49_dialog_content = "หลังจบการทดสอบแล้ว เตรียมเข้าพบผู้อาวุโสได้เลยนะ",
  ui_story_5004_50041901_50_dialog_content = "ขอบคุณค่ะ",
  ui_story_5004_50041901_51_dialog_content = "อ้าว!",
  ui_story_5004_50041901_52_dialog_content = "สโมกกี้? มาทำอะไรที่นี่น่ะ",
  ui_story_5004_50041901_53_dialog_content = "เห็นเขาจัดสอบอะไรซักอย่างกันใช่มั้ย ฉันอยากมาลองด้วยน่ะ",
  ui_story_5004_50041901_54_dialog_content = "แค่ใช้ลูมินาติกส์โจมตีเป้าซ้อมก็พอใช่มั้ย?",
  ui_story_5004_50041901_55_dialog_content = "อ๊ะ โอ้โห นี่มัน...",
  ui_story_5004_50041901_56_dialog_content = "เหลือเชื่อจริง ๆ! เด็กผู้หญิงตัวนิดเดียวทำไมถึงมีพลังแข็งแกร่งขนาดนี้?",
  ui_story_5004_50041901_57_dialog_content = "เธอชื่ออะไร? มาจากตระกูลอะไรน่ะ?",
  ui_story_5004_50041901_58_dialog_content = "หืม? จะให้รางวัลฉันหรือไง? ฉันไม่อยากได้ของดาด ๆ หรอกนะ",
  ui_story_5004_50041901_59_dialog_content = "งั้นก็จำให้ดีล่ะ! ฉัน สโมกกี้ จากตระกูลแมนติคอร์!",
  ui_story_5004_50041901_60_dialog_content = "สโมกกี้ ตระกูลแมนติคอร์...",
  ui_story_5004_50041901_61_dialog_content = "ไม่มีอย่างอื่นให้ทำแล้วเหรอ? แค่นี้เนี่ยนะ?",
  ui_story_5004_50041901_62_dialog_content = "ใช่! รอก่อนนะ! ผู้อาวุโสอยากจะคุยกับเธอ...",
  ui_story_5004_50041901_63_dialog_content = "รอเหรอ? ไม่เอาน่า ฉันรอไม่ไหวหรอก นี่ยังต้องไปช้อปเสื้อผ้าอีก",
  ui_story_5004_50041901_64_dialog_content = "เจเนวีฟ มาด้วยกันมั้ย? ไปช้อปปิ้งกันเถอะ!",
  ui_story_5004_50041901_65_dialog_content = "เธอ...",
  ui_story_5004_50041901_66_dialog_content = "ฟังนะ เจเนวีฟ...",
  ui_story_5004_50041901_67_dialog_content = "ลูกได้พลาดโอกาสครั้งเดียวในชีวิตไปแล้ว",
  ui_story_5004_50041901_68_dialog_content = "ไม่เป็นไรนะ ตระกูลซาลาร์สยินดีส่งทหารมาปกป้องเพเทียเบิร์ก",
  ui_story_5004_50041901_69_dialog_content = "แต่เราคงหมดโอกาสเป็นพันธมิตรกับพวกเขาแล้ว",
  ui_story_5004_50041901_70_dialog_content = "ลูกไปพักผ่อนเถอะ",
  ui_story_5004_50041901_71_dialog_content = "ขอโทษนะคะ คุณพ่อ",
  ui_story_5004_50041901_72_dialog_content = "(ทำไมเธอต้องทำแบบนี้ด้วย สโมกกี้?)",
  ui_story_5004_50041901_73_dialog_content = "เธอแค่อยากจะแข่งกับฉันจริง ๆ เหรอ? อยากเอาชนะฉันงั้นเหรอ? หรือว่า...)",
  ui_story_5004_50041901_74_dialog_content = "เจเนวีฟ!",
  ui_story_5004_50041901_75_dialog_content = "มีอะไรเหรอคะ คุณแม่?",
  ui_story_5004_50041901_76_dialog_content = "ลูกรู้หรือเปล่า?",
  ui_story_5004_50041901_77_dialog_content = "ตระกูลซาลาร์สทำสัญญากับตระกูลแมนติคอร์แล้วนะ...",
  ui_story_5004_50041901_78_dialog_content = "ค่ะ พวกเขาจะให้สโมกกี้แต่งงานเข้าตระกูลใช่มั้ยคะ",
  ui_story_5004_50041901_79_dialog_content = "แต่เด็กผู้หญิงนั่นดันหนีไปน่ะสิ!",
  ui_story_5004_50041901_80_dialog_content = "ว่าไงนะคะ?",
  ui_story_5004_50041901_81_dialog_content = "สโมกกี้หนีออกจากบ้านงั้นเรอะ?",
  ui_story_5004_50041901_82_dialog_content = "บ้าเอ๊ย! ไม่น่าให้โอกาสพวกเพเทียเบิร์กหลังเขาเลย ให้ตายสิ!",
  ui_story_5004_50041901_83_dialog_content = "เสียเวลาชะมัด แต่มองโลกในแง่ดี อย่างน้อยเราก็ไม่ต้องทนอยู่เมืองบ้านนอก ๆ แบบนี้อีกล่ะนะ",
  ui_story_5004_50041901_84_dialog_content = "ทุกคนจนฟัง! ท่านผู้อาวุโสบอกว่าเพเทียเบิร์ก \"ไม่ต้องการการคุ้มครองจากลูโมโพลิสแล้ว\"! ถอนกำลังเดี๋ยวนี้! กลับเมืองกันได้แล้ว!",
  ui_story_5004_50041901_85_dialog_content = "นั่นทำให้เพเทียเบิร์กที่อ่อนแออยู่แล้วยิ่งเสื่อมอำนาจลงไปอีก",
  ui_story_5004_50041901_86_dialog_content = "จากนั้นคุณแม่ก็เสียชีวิตจากอุบัติเหตุ แล้วคุณพ่อก็ล้มป่วย",
  ui_story_5004_50041901_87_dialog_content = "เจเนวีฟ...",
  ui_story_5004_50041901_88_dialog_content = "ลูกอยู่นี่ค่ะ คุณพ่อ",
  ui_story_5004_50041901_89_dialog_content = "ตระกูลที่ลูกปฏิญาณว่าจะปกป้อง มันกำลังจะถึงจุดจบแล้ว...",
  ui_story_5004_50041901_90_dialog_content = "ลูก... เสียใจ... หรือว่าสบายใจกันล่ะ? ลูกคิดว่าจะทำยังไงกับอนาคตงั้นรึ?",
  ui_story_5004_50041901_91_dialog_content = "ไม่รู้สิคะ คุณพ่อ... ทุกอย่างเกิดขึ้นเร็วเหลือเกิน ลูกยังคิดอะไรไม่ออกเลย",
  ui_story_5004_50041901_92_dialog_content = "เด็กน้อยผู้น่าสงสาร...",
  ui_story_5004_50041901_93_dialog_content = "...",
  ui_story_5004_50041901_94_dialog_content = "อันนา แกก็จะทิ้งฉันไปเหมือนกันเหรอ",
  ui_story_5004_50041901_95_dialog_content = "ฮี้...",
  ui_story_5004_50041901_96_dialog_content = "สาวน้อย ม้าตัวนี้เป็นเพื่อนของเธองั้นรึ?",
  ui_story_5004_50041901_97_dialog_content = "ค่ะ",
  ui_story_5004_50041901_98_dialog_content = "ฉันช่วยมันได้นะ แต่เธอจะต้อง...",
  ui_story_5004_50041901_99_dialog_content = "ได้ค่ะ! ฉันยอมทำทุกอย่าง! ฉันต้องการอันนา! ฉันต้องการเพื่อนที่จะอยู่กับฉัน เพื่อตามหาผู้หญิงคนนั้น!",
  ui_story_5004_50041901_100_dialog_content = "สโมกกี้...",
  ui_story_5004_50041901_100X1_dialog_content = "อ้าว คุณเจเนวีฟนี่นา?",
  ui_story_5004_50041901_100X2_dialog_content = "เธอรู้จักฉันด้วยเหรอ มีธุระอะไรก็พูดมา ฉันไม่ว่างคุยเล่นหรอกนะ",
  ui_story_5004_50041901_100X3_dialog_content = "โอ้ คุณจะต้องสนใจแน่ ฉันมีข่าวของสโมกกี้มาบอกน่ะ",
  ui_story_5004_50041901_100X4_dialog_content = "!!",
  ui_story_5004_50041901_100X5_dialog_content = "เธอรู้จักสโมกกี้ด้วยเหรอ?",
  ui_story_5004_50041901_100X6_dialog_content = "แน่นอน และฉันก็รู้ด้วยว่าเธออยู่ที่หาดบันไดสวรรค์...",
  ui_story_5004_50041901_100X7_dialog_content = "นี่ อย่าพึ่งไปสิ ฉันยังพูดไม่จบเลยนะ!",
  ui_story_5004_50041901_102_dialog_content = "คุณเจเนวีฟ",
  ui_story_5004_50041901_103_dialog_content = "คุณเจเนวีฟ!",
  ui_story_5004_50041901_104_dialog_content = "ว่าไง",
  ui_story_5004_50041901_105_dialog_content = "เราพร้อมส่งเสียงเชียร์หน้าเวทีตามที่สั่งแล้วครับ",
  ui_story_5004_50041901_106_dialog_content = "ดีมาก คราวนี้ล่ะ ฉันจะสู้กับเธอตัวต่อตัว",
  ui_story_5004_50041901_107_dialog_content = "ฉันจะเอาชนะ... ไม่สิ ฉันจะกำจัดเธอด้วยเสียงเพลงของฉัน!",
  ui_story_5004_50042001_1_dialog_content = "เวทีสวยสุด ๆ เลยแฮะ ผลงานออกแบบของเฟลอร์เหรอเนี่ย?",
  ui_story_5004_50042001_2_dialog_content = "ดูจากของตกแต่งสไตล์เรดีเซล เวรนช์ ก็น่าจะใช่แหละ",
  ui_story_5004_50042001_3_dialog_content = "มีเรื่องที่เขาไม่เก่งบ้างมั้ยเนี่ย",
  ui_story_5004_50042001_4_dialog_content = "นายจะไม่มากับเราจริง ๆ เหรอ PlayerName?",
  ui_story_5004_50042001_5_dialog_content = "ขอผ่านดีกว่า เรื่องร้องเพลงนี่ฉันไม่ถนัดเลย",
  ui_story_5004_50042001_6_dialog_content = "ส่วนฉัน... ถ้าต้องเจอคนเยอะ ๆ... ฉันคงไม่ไหวค่ะ",
  ui_story_5004_50042001_7_dialog_content = "ส่วนฉันก็ต้องดูแลเจ้าเบริล เพราะงั้นหมดสิทธิ์",
  ui_story_5004_50042001_8_dialog_content = "เอ่อ ฉันจะเชียร์ทุกคนกับราฟาเอลให้เต็มที่ค่ะ!",
  ui_story_5004_50042001_9_dialog_content = "ไว้ใจฉันได้เลย! เดี๋ยวพอโชว์ถึงไคลแม็กซ์ ฉันจะโปรยมิสไซล์ให้ทุกคนเอง!",
  ui_story_5004_50042001_10_dialog_content = "อย่านะ! ได้โปรดเถอะ!",
  ui_story_5004_50042001_11_dialog_content = "เอาล่ะ ฝากด้วยนะทุกคน!",
  ui_story_5004_50042001_12_dialog_content = "เตรียมสนุกสุดเหวี่ยงกับโชว์ของเราได้เลย อย่าลืมเชียร์ด้วยนะ!",
  ui_story_5004_50042001_13_dialog_content = "ในที่สุดเราก็มาถึงการแข่งขันนัดสุดท้ายของงานราชันเจ้าสมุทรกันแล้ว นั่นก็คือการประกวดสติปัญญาและความงดงาม นั่นก็คือการแสดงดนตรีสดบนชายหาด!",
  ui_story_5004_50042001_14_dialog_content = "ด้วยสปอนเซอร์ที่หลั่งไหลเข้ามามากมาย เราจึงสามารถเชิญกรรมการคนดังมาตัดสินการแข่งขันครั้งนี้ได้ถึง 2 ท่าน!",
  ui_story_5004_50042001_15_dialog_content = "ขอเชิญพบกับ กรรมการ ช ผู้ไม่ประสงค์ออกนามแห่งลูโมโพลิส!",
  ui_story_5004_50042001_16_dialog_content = "อะแฮ่ม",
  ui_story_5004_50042001_17_dialog_content = "และกรรมการ อ จากอัมบราตัน!",
  ui_story_5004_50042001_18_dialog_content = "สวัสดี ทุกคน",
  ui_story_5004_50042001_19_dialog_content = "กรรมการที่โบนาชีเชิญมาทำไมดูคุ้น ๆ จัง?",
  ui_story_5004_50042001_20_dialog_content = "กรรมการและผู้ชมทุกคนจะเป็นผู้ตัดสินผู้ชนะในครั้งนี้!",
  ui_story_5004_50042001_21_dialog_content = "ผู้เข้าแข่งขันคนแรก...",
  ui_story_5004_50042001_22_dialog_content = "คือนักร้องเฮฟวี่เมทัลจากขุมนรกผู้สวมหน้ากาก...",
  ui_story_5004_50042001_23_dialog_content = "ฉันชื่อเซลูลูลู่ นักร้องผู้ลึกลับจากอัมบราตัน!",
  ui_story_5004_50042001_24_dialog_content = "นั่นมันเซลูซิดนี่นา? แค่ดูชื่อกับหมวกก็รู้แล้วไม่ใช่เรอะ!",
  ui_story_5004_50042001_25_dialog_content = "เอาล่ะ ขอฉันได้ส่งเสียงคำรามจากก้นบึ้งของจิตวิญญาณ!",
  ui_story_5004_50042001_26_dialog_content = "และมอบการแสดงเฮฟวี่เมทัลสุดระห่ำให้ทุกคนด้วยเถอะ!",
  ui_story_5004_50042001_27_dialog_content = "ลงจากเวทีไปได้แล้ว!",
  ui_story_5004_50042001_28_dialog_content = "ออกไป ออกไป!",
  ui_story_5004_50042001_29_dialog_content = "นี่มันการแสดงสดในชุดว่ายน้ำนะ!",
  ui_story_5004_50042001_30_dialog_content = "ไม่มีชุดว่ายน้ำแล้วจะขึ้นมาทำไม?",
  ui_story_5004_50042001_31_dialog_content = "ไม่เห็นเหมือนที่โฆษณาเลย!",
  ui_story_5004_50042001_32_dialog_content = "ฉันมาดูสาว ๆ ใส่บิกินี่ต่างหาก! คืนเงิน! คืนเงินมาเดี๋ยวนี้!",
  ui_story_5004_50042001_33_dialog_content = "น่าขายหน้าชะมัด... ดีนะที่ฉันไม่บอกชื่อจริงไป",
  ui_story_5004_50042001_34_dialog_content = "เอาล่ะ หวังว่าจะได้เจอกันอีกนะทุกคน!",
  ui_story_5004_50042001_35_dialog_content = "อ้าว ไหงตัดจบแบบนี้ล่ะเนี่ย เร็วไปมั้ย~",
  ui_story_5004_50042001_36_dialog_content = "น่าเสียดายจัง คุณหน้ากากแมวน่าจะเสียงดีเหมือนกันนะ...",
  ui_story_5004_50042001_37_dialog_content = "อย่าโดนหลอกด้วยหน้าตานะ เบริล!",
  ui_story_5004_50042001_38_dialog_content = "แต่เซลูซิดทำแบบนี้ก็ดีเหมือนกัน",
  ui_story_5004_50042001_39_dialog_content = "ได้เขามาลดความคาดหวังคนดูแบบนี้ สาว ๆ ทีมเราจะต้องได้คะแนนเยอะแน่ ๆ!",
  ui_story_5004_50042001_40_dialog_content = "ต่อไปคือ... เฟลอร์กับบร็อคงั้นเหรอ?",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>บร็อคโค้งให้ผู้ชม จากนั้นก็หันไปผายมือ...</color>",
  ui_story_5004_50042001_42_dialog_content = "สวัสดีทุกคน——",
  ui_story_5004_50042001_43_dialog_content = "กรี๊ดดดดดดดด!",
  ui_story_5004_50042001_44_dialog_content = "เห็นรึเปล่า? เฟลอร์ยิ้มให้ฉันด้วย!",
  ui_story_5004_50042001_45_dialog_content = "ตายแล้ว สายตาของเธอมันแทงมาที่กลางใจเลย เฟลอรี่! หัวใจของฉันมันกำลังรุ่มร้อนด้วยความรัก!",
  ui_story_5004_50042001_46_dialog_content = "แคว้ก แคว้ก!",
  ui_story_5004_50042001_47_dialog_content = "นกนางนวลก็มา! แกควรไปหาปลาไม่ใช่เรอะ?",
  ui_story_5004_50042001_48_dialog_content = "เอาจริงเหรอ?",
  ui_story_5004_50042001_49_dialog_content = "แน่นอน เพื่อนรัก!",
  ui_story_5004_50042001_50_dialog_content = "ทำไมบร็อคถึงหยิบแท่งเหล็กออกมาล่ะ?!",
  ui_story_5004_50042001_51_dialog_content = "เดี๋ยวนะ นี่จะเล่นมายากลเหรอ?",
  ui_story_5004_50042001_52_dialog_content = "แล้วดันเลือกคนหัวทึบที่สุดในเรดีเซล เวรนช์ อย่างบร็อคซะด้วย จะไหวมั้ยเนี่ย?",
  ui_story_5004_50042001_53_dialog_content = "กรี๊ดดดด!",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>แท่งเหล็กเสียบผ้าที่ปิดไว้เข้าไปในตู้ จนปลายทะลุออกมาอีกด้าน</color>",
  ui_story_5004_50042001_55_dialog_content = "เฟลอร์!",
  ui_story_5004_50042001_56_dialog_content = "ตู้ส่ายนิดหน่อยแฮะ...",
  ui_story_5004_50042001_57_dialog_content = "คุณเฟลอร์จะเป็นอะไรมั้ยนะ? น่ากลัวจัง...",
  ui_story_5004_50042001_58_dialog_content = "ไม่เป็นไรนะ ฉันพร้อมรักษาฉุกเฉินแล้ว",
  ui_story_5004_50042001_59_dialog_content = "จะไม่มีใครตายใช่มั้ย?",
  ui_story_5004_50042001_60_dialog_content = "(บร็อคตัวสั่นแล้วก็พูดพึมพำกับตัวเอง นั่นสวดมนตร์อยู่เรอะ...?)",
  ui_story_5004_50042001_61_dialog_content = "ตู้นิ่งไปแล้ว... ราฟาเอล!",
  ui_story_5004_50042001_62_dialog_content = "ได้เลย เตรียมยิง!",
  ui_story_5004_50042001_63_dialog_content = "เดี๋ยวก่อน!",
  ui_story_5004_50042001_64_dialog_content = "ยู้ฮู่ว!",
  ui_story_5004_50042001_65_dialog_content = "ว้าว เหลือเชื่อจริง ๆ!",
  ui_story_5004_50042001_66_dialog_content = "ยอดเลย...",
  ui_story_5004_50042001_67_dialog_content = "ว้า เสียแรงเปล่าซะได้ เมื่อกี้ฉันจะยิงแล้วนะเนี่ย!",
  ui_story_5004_50042001_68_dialog_content = "ยิง? มิสไซล์เนี่ยนะ? แบบนั้นมันเรียกว่ารักษาได้ด้วยเหรอ?",
  ui_story_5004_50042001_69_dialog_content = "ดูเหมือนทุกคนจะชอบการแสดงแฮะ ปรบมือกันใหญ่เลย",
  ui_story_5004_50042001_70_dialog_content = "ฉันปรบมือเพราะคุณเฟลอร์ยังไม่ตายน่ะ...",
  ui_story_5004_50042001_71_dialog_content = "เดี๋ยวนะ ฉันบอกไปแล้วไม่ใช่เหรอ ว่าอนุญาตให้โชว์ร้องเพลงได้อย่างเดียวน่ะ?",
  ui_story_5004_50042001_72_dialog_content = "ทำผิดกฎแบบนี้ไม่น่ารักเลยนะ บร็อค เฟลอร์ แถมพวกนายเป็นสตาฟที่ควรจะรู้กฎดีกว่าคนอื่นแท้ ๆ?",
  ui_story_5004_50042001_73_dialog_content = "ฮ่าฮ่า โทษทีนะ เราก็แค่อยากจะมอบความสนุกให้ผู้ชมน่ะ บรรยากาศมันจะได้ครึกครื้นหน่อย",
  ui_story_5004_50042001_74_dialog_content = "แล้วฉันก็ร้องเพลงไม่เป็น เลยคิดว่าแบบนี้น่าจะดีกว่า",
  ui_story_5004_50042001_75_dialog_content = "ผู้หญิงนั่นเป็นใครกัน บังอาจมาสั่งสอนเฟลอร์แบบนั้น!",
  ui_story_5004_50042001_76_dialog_content = "เฟลอร์! เรารักคุณ!",
  ui_story_5004_50042001_77_dialog_content = "(ที่จริงกลายเป็นทาเลนต์โชว์มันก็ไม่เลวนะ)",
  ui_story_5004_50042001_78_dialog_content = "(น่าเสียดายจังที่เซลูซิดต้องลงจากเวทีไปก่อน)",
  ui_story_5004_50042001_79_dialog_content = "(ไม่ได้สิ เขาไม่มีชุดว่ายน้ำ แบบนั้นไปประกวดรายการจำพวกหน้ากากนักร้องน่าจะดีกว่า)",
  ui_story_5004_50042001_80_dialog_content = "กฎก็ต้องเป็นกฎ ฉันขอปรับให้เฟลอร์ตกรอบ",
  ui_story_5004_50042001_81_dialog_content = "ทำไมต้องจำกัดแค่ร้องเพลงด้วย?!",
  ui_story_5004_50042001_82_dialog_content = "มาแสดงในห้องเราเมื่อไหร่ก็ได้เลยนะ เฟลอร์!",
  ui_story_5004_50042001_83_dialog_content = "โฮ่ง โฮ่ง!",
  ui_story_5004_50042001_84_dialog_content = "เมี้ยว!",
  ui_story_5004_50042001_85_dialog_content = "ขนาดสัตว์แถวนี้ยังมาเลยเหรอ! พลังของเฟลอร์นี่น่ากลัวจัง...",
  ui_story_5004_50042001_86_dialog_content = "ผู้เข้าแข่งขันหมายเลข 8!",
  ui_story_5004_50042001_87_dialog_content = "เจเนวีฟ วรอนสกี้!",
  ui_story_5004_50042001_88_dialog_content = "หึหึ คู่แข่งของฉันมีฝีมือแค่นี้เองเหรอ",
  ui_story_5004_50042001_89_dialog_content = "ฉันจะใช้โอกาสนี้สร้างความประทับใจให้กรรมการกับผู้ชม แล้วก็โกยคะแนนให้ได้เยอะ ๆ!",
  ui_story_5004_50042001_90_dialog_content = "(ผู้แข่งขันประหลาด ๆ อีกแล้ว...)",
  ui_story_5004_50042001_91_dialog_content = "(เมื่อไหร่จะถึงตาไวซ์นะ?)",
  ui_story_5004_50042001_92_dialog_content = "ถึงตาคุณเจเนวีฟแล้วนะ PlayerName",
  ui_story_5004_50042001_93_dialog_content = "อื้ม เธอน่าจะเป็นคู่แข่งที่เก่งที่สุดในตอนนี้แล้วล่ะ",
  ui_story_5004_50042001_94_dialog_content = "ร่วงหล่นมาจากพายุฟ้ากระหน่ำ♪",
  ui_story_5004_50042001_95_dialog_content = "...!!",
  ui_story_5004_50042001_96_dialog_content = "นี่คือทัณฑ์อันโหดร้ายจากสวรรค์ หรือการปลดปล่อยจากพันธนาการ♪",
  ui_story_5004_50042001_97_dialog_content = "บนเส้นขอบฟ้าอันแสนไกล♪",
  ui_story_5004_50042001_98_dialog_content = "เงาของเธอช่างเลือนราง♪",
  ui_story_5004_50042001_99_dialog_content = "ความรักและคิดถึงที่รุนแรงราวกับลมฝน♪",
  ui_story_5004_50042001_100_dialog_content = "ปัดเป่าสิ่งเลวร้ายให้มลายหายไป♪",
  ui_story_5004_50042001_101_dialog_content = "เปิดหนทางสู่วันใหม่ด้วยรักอันแน่วแน่♪",
  ui_story_5004_50042001_102_dialog_content = "และจบความบาดหมางอันไร้ความหมายเสียที♪",
  ui_story_5004_50042001_103_dialog_content = "เธอ... ร้องเพลงเพราะจัง",
  ui_story_5004_50042001_104_dialog_content = "...",
  ui_story_5004_50042001_105_dialog_content = "โว้ววว เจเนวีฟ!",
  ui_story_5004_50042001_106_dialog_content = "เป็นเพลงที่สะเทือนอารมณ์มาก ๆ และทุกคนในที่นี้ก็รู้สึกได้",
  ui_story_5004_50042001_107_dialog_content = "เสียงของเจเนวีฟตรงเข้าไปกลางหัวใจฉันเลย ถ้าเธอมาเปิดคอนเสิร์ตที่อัมบราตันบ้างก็ดีน่ะสิ",
  ui_story_5004_50042001_108_dialog_content = "กรรมการสรุปผลเป็นที่เรียบร้อยแล้ว เจเนวีฟได้ 9.6 คะแนน!",
  ui_story_5004_50042001_109_dialog_content = "ยินดีด้วย เป็นคะแนนที่สูงมากเลยนะนั่น",
  ui_story_5004_50042001_110_dialog_content = "ขอบคุณสำหรับการแสดงนะ เจเนวีฟ",
  ui_story_5004_50042001_111_dialog_content = "หึหึ เห็นรึยังล่ะ สโมกกี้?",
  ui_story_5004_50042001_112_dialog_content = "ยอดไปเลย...",
  ui_story_5004_50042001_113_dialog_content = "เป็นเพลงที่เต็มไปด้วยอารมณ์ความรู้สึกจริง ๆ",
  ui_story_5004_50042001_114_dialog_content = "(เพลงของเจเนวีฟไพเราะอย่างคาดไม่ถึง ชนะใจคนดูไปเยอะแน่ ๆ นี่ยังไม่นับแฟนคลับเดิมนะ)",
  ui_story_5004_50042001_115_dialog_content = "(ชักเป็นห่วงไวซ์แล้วสิ...)",
  ui_story_5004_50042001_116_dialog_content = "ต่อไป เป็นการแสดงของสามสาววง \"แมนติคอร์คิส\"!",
  ui_story_5004_50042001_117_dialog_content = "ถึงตาไวซ์แล้ว!",
  ui_story_5004_50042001_118_dialog_content = "มาจนได้นะ! เฮ่อ ตื่นเต้นจัง",
  ui_story_5004_50042001_119_dialog_content = "ฉันก็เหมือนกัน!",
  ui_story_5004_50042001_120_dialog_content = "♪—",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "สาวน้อยผู้เดียวดาย วันนี้เธอจะเดินทางไปที่ใด♪",
  ui_story_5004_50042001_123_dialog_content = "ณ ชายหาดยามค่ำคืน ใต้แสงไฟจากประภาคาร♪",
  ui_story_5004_50042001_124_dialog_content = "โอ้โห!",
  ui_story_5004_50042001_125_dialog_content = "ฮูเร่ ฮูเร่ ฮูเร่!",
  ui_story_5004_50042001_126_dialog_content = "(ว้าว... ขนาดแฟนคลับของเจเนวีฟยังส่งเสียงเชียร์แล้วก็ปรบมือไม่หยุด)",
  ui_story_5004_50042001_127_dialog_content = "กลิ่นของทะเลพัดโชยข้ามหาดทราย ใต้ฟ้าดาราพราว♪",
  ui_story_5004_50042001_128_dialog_content = "โอบกอดและหล่อเลี้ยงดอกไม้งามในความเงียบงัน ให้เติบโตอย่างกล้าหาญและแข็งแกร่ง♪",
  ui_story_5004_50042001_129_dialog_content = "ยืนหยัดท้าทายคลื่นสูงถาโถม เพื่อคว้าชัยมาครอง♪",
  ui_story_5004_50042001_130_dialog_content = "คาร์ลีน! เจ้าไวซ์! เจ้าสโมกกี้! สุดยอดเลย!",
  ui_story_5004_50042001_131_dialog_content = "นี่นี่ เบริล จับมือฉันสิ เราโบกมือให้พวกนั้นกันเถอะ!",
  ui_story_5004_50042001_132_dialog_content = "อื้อ!",
  ui_story_5004_50042001_133_dialog_content = "จงเอื้อมมือคว้าแสงสว่างด้วยใจอันไม่ย่อท้อ♪",
  ui_story_5004_50042001_134_dialog_content = "สัมผัสกับดวงใจที่ร้องคำรามราวกับจะระเบิดออก♪",
  ui_story_5004_50042001_135_dialog_content = "สูบฉีดด้วยจังหวะอันแสนเร้าใจ♪",
  ui_story_5004_50042001_136_dialog_content = "สู่จุดหมายด้วยพลังอันเหนือจินตนาการ♪",
  ui_story_5004_50042001_137_dialog_content = "พุ่งทะยานอย่าหยุดยั้ง♪",
  ui_story_5004_50042001_138_dialog_content = "ล่องลอยสูงเหนือฟ้าไกล♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>ขณะที่มือข้างหนึ่งจับไมค์ สโมกกี้ก็ใช้มืออีกข้างทำท่ายิงปืนใส่เจเนวีฟ จากนั้นก็จบเพลงด้วยการวิงค์ตาข้างหนึ่ง</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>แมนติคอร์คิส จบการแสดงอย่างสมบูรณ์แบบ</color>",
  ui_story_5004_50042001_141_dialog_content = "...",
  ui_story_5004_50042001_142_dialog_content = "(เอ๊ะ เธอมาอยู่นี่ตั้งแต่เมื่อไหร่?)",
  ui_story_5004_50042001_143_dialog_content = "ไม่เลว ถึงแต่ก่อนวงมันจะมีแค่สองคนน่ะนะ",
  ui_story_5004_50042001_144_dialog_content = "หา?",
  ui_story_5004_50042001_145_dialog_content = "(เธอไปซะแล้ว เมื่อกี้เธอหัวเราะงั้นเหรอ? ว่าแต่มันหมายความว่ายังไงกันนะ?)",
  ui_story_5004_50042001_146_dialog_content = "แมนติคอร์คิส! แมนติคอร์คิส! แมนติคอร์คิส!",
  ui_story_5004_50042001_147_dialog_content = "ยอดเลย แมนติคอร์คิส!",
  ui_story_5004_50042001_148_dialog_content = "ทุกคนชอบการแสดงมาก ๆ แม้แต่เบริลก็ยังดูตื่นเต้นสุด ๆ",
  ui_story_5004_50042001_149_dialog_content = "เอ้า! อัดวิดีโอไว้หมดแล้วใช่มั้ย?",
  ui_story_5004_50042001_150_dialog_content = "ครับ ท่านเจ้าเมื... คุณกรรมการ!",
  ui_story_5004_50042001_151_dialog_content = "เป็นส่วนผสมที่... น่าสนใจจริง ๆ",
  ui_story_5004_50042001_154_dialog_content = "แมนติคอร์คิส...",
  ui_story_5004_50042001_155_dialog_content = "ได้ 10 คะแนนเต็ม!",
  ui_story_5004_50042201_1_dialog_content = "ชนแก้ว!",
  ui_story_5004_50042201_2_dialog_content = "ฮ่า!",
  ui_story_5004_50042201_3_dialog_content = "อะไรเนี่ย ชนแก้วด้วยน้ำผลไม้เนี่ยนะ! ทำตัวเป็นเด็กน้อยไปได้!",
  ui_story_5004_50042201_4_dialog_content = "แต่น้ำมันที่นายชอบมันก็ไม่ใช่แอลกอฮอล์เหมือนกันนะ?",
  ui_story_5004_50042201_5_dialog_content = "ไม่ต้องพูดเลย!",
  ui_story_5004_50042201_6_dialog_content = "ฮ่าฮ่าฮ่า!",
  ui_story_5004_50042201_7_dialog_content = "คาร์ลีน ไวซ์ สโมกกี้ ร้องเพลงได้เยี่ยมไปเลยน้า~!",
  ui_story_5004_50042201_8_dialog_content = "แถมยังเต้นเหมือนซูเปอร์สตาร์อีก! ฉันนี่อึ้งไปเลย!",
  ui_story_5004_50042201_9_dialog_content = "ขนาดเบริลยังปลื้มจนน้ำตาไหลเลย เนอะ ๆ?",
  ui_story_5004_50042201_10_dialog_content = "เอ่อ... ค่ะ เป็นการแสดงที่วิเศษมาก ๆ เลย",
  ui_story_5004_50042201_11_dialog_content = "ทั้งเสียงร้องแล้วก็การแสดงบทเวที ทุกอย่างมีเสน่ห์จริง ๆ",
  ui_story_5004_50042201_12_dialog_content = "เป็นโชว์ที่ไร้ที่ติ เหมือนที่เบริลบอกนั่นแหละ!",
  ui_story_5004_50042201_13_dialog_content = "ว่าแต่รางวัลปริศนาคืออะไรกันนะ?",
  ui_story_5004_50042201_14_dialog_content = "นั่นสิ ฉันก็อยากรู้เหมือนกัน",
  ui_story_5004_50042201_15_dialog_content = "ถึงจะถามโบนาชีไป เธอคงยิ้มอย่างมีเลศนัยแล้วก็บอกให้เรารอวันพรุ่งนี้",
  ui_story_5004_50042201_16_dialog_content = "มันคืออะไรกันนะ ขนาดฉันยังอยากรู้เลย",
  ui_story_5004_50042201_17_dialog_content = "ถ้าเป็นน้ำเชื่อมอร่อย ๆ ก็ดีน่ะสิ ร้านน้ำแข็งไสของฉันจะได้มีลูกค้าเยอะ ๆ!",
  ui_story_5004_50042201_18_dialog_content = "ฉันควรไปเปิดร้านน้ำแข็งไสบนลูโมโพลิสดีมั้ยนะ!",
  ui_story_5004_50042201_19_dialog_content = "แบบนั้น ราฟาเอลจะไล่จับคุณในข้อหาขายของบนทางเท้านะคะ",
  ui_story_5004_50042201_20_dialog_content = "ฮิฮิ ถ้าเป็นไวซ์เดี๋ยวฉันต่อให้หนีก่อน 1 นาที!",
  ui_story_5004_50042201_21_dialog_content = "ว่าไง ยินดีด้วยนะทุกคน",
  ui_story_5004_50042201_22_dialog_content = "ขอบคุณนะ เจเนวีฟ... นี่คุณมาแสดงความยินดีกับเราโดยเฉพาะเลยเหรอ?",
  ui_story_5004_50042201_23_dialog_content = "แน่นอน ฉันเป็นชนชั้นสูงน่ะ",
  ui_story_5004_50042201_24_dialog_content = "เห็นฉันเป็นใครกัน เด็กผู้หญิงที่งอแงเวลาแพ้หรือไง?",
  ui_story_5004_50042201_25_dialog_content = "คราวนี้ไม่ร้องไห้เหรอ? เดี๋ยวนี้โตขึ้นเยอะเลยนะ แต่ก่อนเธอขี้แงจะตาย~",
  ui_story_5004_50042201_26_dialog_content = "หา? ฉันจะฆ่าเธอเดี๋ยวนี้ล่ะ!",
  ui_story_5004_50042201_27_dialog_content = "เอาน่า เอาน่า มานั่งด้วยกันเถอะ เดี๋ยวฉันเลี้ยงเหล้าไถ่โทษเรื่องเมื่อก่อนก็แล้วกัน",
  ui_story_5004_50042201_28_dialog_content = "สโมกกี้คว้าแขนของเจเนวีฟแล้วลากเธอมานั่งเก้าอี้ข้าง ๆ",
  ui_story_5004_50042201_29X1_dialog_content = "ลองนี่สิ!",
  ui_story_5004_50042201_29X2_dialog_content = "ชิ น่าหงุดหงิดจริง ๆ",
  ui_story_5004_50042201_29X3_dialog_content = "นี่มัน...?",
  ui_story_5004_50042201_29X4_dialog_content = "ใช่ เหมือนร้านเหล้าในเพเทียเบิร์กที่เราไปดื่มกันบ่อย ๆ เลยเนอะ",
  ui_story_5004_50042201_29X5_dialog_content = "ก็เกือบ ๆ นะ ฉันจำไม่ค่อยได้หรอก มันตั้งนานมาแล้วนี่นา!",
  ui_story_5004_50042201_29X6_dialog_content = "แมนติคอร์คิส ทำไมต้องใช้ชื่อนั้นด้วย",
  ui_story_5004_50042201_29X7_dialog_content = "เหมือนเหล้าแก้วนี้นั่นแหละ เธอน่าจะรู้เหตุผลนะ ฉันว่าจริง ๆ เธอยังไม่ลืมหรอก",
  ui_story_5004_50042201_29X8_dialog_content = "...",
  ui_story_5004_50042201_30_dialog_content = "(ระหว่างสองคนนี้มันซับซ้อนจังแฮะ)",
  ui_story_5004_50042201_31_dialog_content = "ฉันอยากดูมายากลของคุณเฟลอร์อีกจัง",
  ui_story_5004_50042201_32_dialog_content = "ยังมองไม่ออกเลยว่าทำได้ยังไง",
  ui_story_5004_50042201_33_dialog_content = "เอาสิ ฉันยินดีแสดงต่อหน้าทุกคนอีกครั้งนะ",
  ui_story_5004_50042201_34_dialog_content = "เอาเป็นที่ที่มันเป็นส่วนตัวกว่านี้มั้ย?",
  ui_story_5004_50042201_35_dialog_content = "แค่พานายฝ่าฝูงชนออกมาฉันก็แทบตายแล้ว แถมยังต้องสู้กับหมาแมวอีก",
  ui_story_5004_50042201_36_dialog_content = "ขอบคุณมากเลยนะ เดี๋ยวฉันทำแผลให้นายทีหลังก็แล้วกัน",
