  ui_story_5004_50042401_8_dialog_content = "อย่าลืมสิว่าเรามาที่นี่เพื่อให้เบริลอาการดีขึ้น",
  ui_story_5004_50042401_9_dialog_content = "แต่ถ้าเธอป่วยมากกว่าเดิมแบบนี้ เราก็อย่าฝืนอยู่ต่อเลย!",
  ui_story_5004_50042401_10_dialog_content = "จริงด้วย เราไปดูอาการเธอกันดีกว่า",
  ui_story_5004_50042401_11_dialog_content = "โอ๊ย! เจ็บจัง มืดแบบนี้ฉันมองไม่เห็นอะไรเลย...",
  ui_story_5004_50042401_12_dialog_content = "โทษที! ไม่เป็นไรนะ โบนาชี?",
  ui_story_5004_50042401_13_dialog_content = "คือว่า เรามีธุระด่วนต้องกลับลูโมโพลิสน่ะ ไว้ค่อยรับรางวัลทีหลังได้มั้ย!",
  ui_story_5004_50042401_14_dialog_content = "หา? ว่าไงนะ?",
  ui_story_5004_50042401_15_dialog_content = "บ้าเอ๊ย ทำไมต้องมามีเรื่องเอาตอนนี้ด้วย?",
  ui_story_5004_50042401_16_dialog_content = "โอเค ทุกคนมากันครบแล้วนะ...",
  ui_story_5004_50042401_17_dialog_content = "เจ้าเบริล...?",
  ui_story_5004_50042401_18_dialog_content = "เบริลไม่อยู่ในห้องงั้นเหรอ? เธอไปไหนน่ะ?",
  ui_story_5004_50042401_19_dialog_content = "หยุดเขย่าได้แล้ว ฉันไม่ได้ทำซักหน่อย",
  ui_story_5004_50042401_20_dialog_content = "ฉันบอกให้เธอพักผ่อนแล้วนี่นา!",
  ui_story_5004_50042401_21_dialog_content = "เร็วเข้า คิดอะไรซักอย่างสิ เธอไปไหนมาไหนด้วยอาการแบบนี้มันอันตรายมากนะ!",
  ui_story_5004_50042401_22_dialog_content = "PlayerName! PlayerName!",
  ui_story_5004_50042401_23_dialog_content = "ใช้พลังจิตของนายช่วยราฟาเอลสิ PlayerName!",
  ui_story_5004_50042401_24_dialog_content = "ก็ได้ ก็ได้... แต่ถ้าไม่หยุดเขย่าฉันก็ใช้พลังไม่ได้นะ!",
  ui_story_5004_50042401_25_dialog_content = "ใจเย็นแล้วปล่อย PlayerName ก่อนเถอะ ราฟาเอล",
  ui_story_5004_50042401_26_dialog_content = "โว่ว...",
  ui_story_5004_50042401_27_dialog_content = "ไม่อยู่ที่โรงแรม",
  ui_story_5004_50042401_28_dialog_content = "แต่ยังพอตามรอยได้",
  ui_story_5004_50042401_29_dialog_content = "ดูเหมือนเธอจะไปที่หน้าผา ตรงที่มีรูปปั้นหินตั้งอยู่",
  ui_story_5004_50042401_30_dialog_content = "บอกทุกคนให้ออกตามหาเบริลเถอะ PlayerName!",
  ui_story_5004_50042401_31_dialog_content = "ทุกคน? มันจำเป็นขนาดนั้นเลยเหรอ?",
  ui_story_5004_50042401_32_dialog_content = "นี่หยุดพักร้อนจนสมองฝ่อแล้วหรือไง PlayerName",
  ui_story_5004_50042401_33_dialog_content = "ที่โรงแรมมันสงบก็เพราะมีมาตรการรักษาความปลอดภัย",
  ui_story_5004_50042401_34_dialog_content = "จำฝูงอิคลิพไซท์ที่เราเจอระหว่างทางได้มั้ย?",
  ui_story_5004_50042401_35_dialog_content = "ถ้าเบริลเกิดไปเจอพวกนั้นขึ้นมาล่ะ จะทำยังไง?",
  ui_story_5004_50042401_36_dialog_content = "แย่แล้ว...",
  ui_story_5004_50042401_37_dialog_content = "ได้เลย ฉันจะบอกทุกคนให้ช่วยหานะ!",
  ui_story_5004_50042401_38_dialog_content = "ขอบคุณที่มานะทุกคน... ไม่นึกเลยว่าคุณเจเนวีฟก็มาด้วย",
  ui_story_5004_50042401_39_dialog_content = "เราเป็นเพื่อนกันแล้วนี่นา ยังไงก็ต้องช่วยเหลือกัน",
  ui_story_5004_50042401_40_dialog_content = "ที่จริงเธอเป็นคนอบอุ่นนะ ถึงจะนิสัยไม่ได้เรื่องก็เหอะ",
  ui_story_5004_50042401_41_dialog_content = "หา? ฉันมาก็เพราะไม่อยากพลาดโอกาสทำให้เธอขายหน้าต่างหาก!",
  ui_story_5004_50042401_42_dialog_content = "อะฮะฮะ... ขอโทษที่ขัดจังหวะนะ แต่เรารีบตามหาเบริลก่อนเถอะ!",
  ui_story_5004_50042401_43_dialog_content = "แน่ใจเหรอว่ามาถูกทาง PlayerName? ป่านี่มันน่าขนลุกชะมัด",
  ui_story_5004_50042401_44_dialog_content = "ใช่สิ เบริลมาทางนี้แน่นอน",
  ui_story_5004_50042401_45_dialog_content = "แต่มันเหมือนเราหลงเป็นวงกลมเลยนะ ที่นี่มันต่างจากตอนกลางวันมากเลย",
  ui_story_5004_50042401_46_dialog_content = "(เส้นทางทอดยาวออกไปเหมือนไม่สิ้นสุด แล้วสัตว์ที่ส่งเสียงแปลก ๆ ก็ไม่รู้ว่าเป็นตัวอะไร...)",
  ui_story_5004_50042401_47_dialog_content = "เดี๋ยวนะ ฉันได้ยินอะไรบางอย่าง",
  ui_story_5004_50042401_48_dialog_content = "เฮ้!",
  ui_story_5004_50042401_49_dialog_content = "เหวอ!",
  ui_story_5004_50042401_50_dialog_content = "โบนาชี? คุณมาทำอะไรที่นี่่น่ะ?",
  ui_story_5004_50042401_51_dialog_content = "ก็นายบอกว่าจะรีบกลับไม่ใช่เหรอ? ฉันก็เลยรีบหาทางนำ<color=#FFB400>รางวัลใหญ่</color>มาให้นายโดยเร็วที่สุดไงล่ะ",
  ui_story_5004_50042401_52_dialog_content = "แล้วทุกคนมาทำอะไรแถวนี้ล่ะเนี่ย?",
  ui_story_5004_50042401_53_dialog_content = "มาผจญภัยส่งท้ายก่อนกลับหรือไง?",
  ui_story_5004_50042401_54_dialog_content = "ฉันขอตามไปด้วยได้มั้ย?",
  ui_story_5004_50042401_55_dialog_content = "ไม่ใช่แล้ว นี่ไม่ใช่การผจญภัยนะ!",
  ui_story_5004_50042401_56_dialog_content = "เบริลหายตัวไป แล้วเราก็ต้องรีบกลับเพราะอาการของเธอแย่ลงเรื่อย ๆ",
  ui_story_5004_50042401_57_dialog_content = "ราฟาเอลกลัวว่าอาการของเธอจะกำเริบ หรือไม่เธอก็อาจจะเจอกับอิคลิพไซท์",
  ui_story_5004_50042401_58_dialog_content = "อืมม... ในเมื่อนี่เป็นเรื่องของเบริล สมาชิกของทรู ออเดอร์ ฉันก็นิ่งดูดายไม่ได้เหมือนกัน",
  ui_story_5004_50042401_59_dialog_content = "แต่ที่นี่อันตรายมากจริง ๆ นอกจากอิคลิพไซท์แล้ว ยังมีพลังความชั่วร้ายอย่างอื่นแฝงอยู่ด้วย!",
  ui_story_5004_50042401_60_dialog_content = "เราไม่ได้มาทดสอบความกล้ากันนะ เลิกขู่อะไรแปลก ๆ ได้แล้ว!",
