  ui_story_5004_50042401_130_dialog_content = "(รีบมาหน่อยนะ PlayerName...)",
  ui_story_5004_50042501_1_dialog_content = "พาเราไปข้างล่างทีสิ โบนาชี!",
  ui_story_5004_50042501_2_dialog_content = "รู้แล้ว ตามฉันมา แล้วก็อยู่ใกล้ ๆ ฉันไว้นะ ถ้าไม่อยากให้ตัวประหลาดนั่นจับได้",
  ui_story_5004_50042501_2X1_dialog_content = "เราจะต้องนำท่อนเพลงไปให้โบนาชีโดยเร็วที่สุด",
  ui_story_5004_50042501_2X2_dialog_content = "จากนั้นให้เคเลสไทต์ปลดผนึกมันออกมา จะได้เล่นบทเพลงปลุกกษัตริย์ผู้โดดเดี่ยวให้ตื่นจากนิทรา",
