  ui_story_5004_50042501_2X4_dialog_content = "แถมตอนนี้ยังต้องหลอกให้เคเลสไทต์ปลดผนึก แล้วก็ต้องให้โบนาชีเล่นเพลงนั่นอีก...",
  ui_story_5004_50042501_2X5_dialog_content = "แน่ใจเหรอครับว่ากษัตริย์อะไรนั่นจะตื่นจริง ๆ? เรากำลังทำอะไรอยู่กันแน่?",
  ui_story_5004_50042501_2X6_dialog_content = "นี่เป็นคำสั่งจากหนึ่งใน 8 อสูร หัวหน้าระดับสูงของพวกเรานะ ฉันรู้มาว่าเจ้ากษัตริย์นี่เป็นอิคลิพไซท์ที่เก่งสุด ๆ",
  ui_story_5004_50042501_2X7_dialog_content = "ถ้าเขาตื่นขึ้นมาล่ะก็ เราจัดการออโรเรียนพวกนี้ได้สบายแน่นอน!",
  ui_story_5004_50042501_2X8_dialog_content = "หวังว่าจะเป็นแบบนั้นนะครับ มืดชะมัดเลย... โอ๊ย ทำไมอยู่ ๆ หยุดเดินล่ะครับ?",
  ui_story_5004_50042501_2X9_dialog_content = "ฉันได้ยินเสียงคนสู้กัน หาที่ซ่อนเร็ว!",
  ui_story_5004_50042501_3_dialog_content = "แอบอยู่ตรงนี้น่าจะปลอดภัย",
  ui_story_5004_50042501_4_dialog_content = "ไม่นึกว่าจะเจอถ้ำอยู่แถวนี้นะเนี่ย แต่มืดจังแฮะ...",
  ui_story_5004_50042501_5_dialog_content = "กรร!",
  ui_story_5004_50042501_6_dialog_content = "หา! มันจะแห่กันมาไม่จบไม่สิ้นเลยหรือไง?",
  ui_story_5004_50042501_7_dialog_content = "เจ้าเบริล ยังไหวรึเปล่า?",
  ui_story_5004_50042501_8_dialog_content = "แฮ่ก แฮ่ก... ฉ-ฉันไม่เป็นไร... ฉันยังสู้ไหว...",
  ui_story_5004_50042501_10_dialog_content = "กรร!",
  ui_story_5004_50042501_11_dialog_content = "กรร!",
  ui_story_5004_50042501_12_dialog_content = "หนอย มันขวางทางเข้าไว้แล้ว!",
  ui_story_5004_50042501_13_dialog_content = "เจ้าพวกชั่ว!",
  ui_story_5004_50042501_14_dialog_content = "ราฟาเอล เบริล!",
  ui_story_5004_50042501_15_dialog_content = "ไม่เป็นไรใช่มั้ย?",
  ui_story_5004_50042501_16_dialog_content = "ช้าจังเลยนะ PlayerName!",
  ui_story_5004_50042501_17_dialog_content = "ทำไมปล่อยให้ผู้หญิงรอนานขนาดนี้ล่ะเนี่ย?",
  ui_story_5004_50042501_18_dialog_content = "โทษทีนะ เอาเป็นว่า ไประบายอารมณ์กับอิคลิพไซท์แทนดีมั้ย?",
  ui_story_5004_50042601_1_dialog_content = "ฟู่ จบซักที",
  ui_story_5004_50042601_2_dialog_content = "ราฟาเอล เบริล บาดเจ็บตรงไหนรึเปล่า?",
  ui_story_5004_50042601_3_dialog_content = "พวกเราปลอดภัยดี ตราบใดที่ฉันยังอยู่ ฉันไม่ให้เจ้าเบริลเป็นอันตรายหรอก!",
  ui_story_5004_50042601_4_dialog_content = "ค่ะ... ราฟาเอลคอยปกป้องฉันไว้...",
  ui_story_5004_50042601_5_dialog_content = "ในเมื่อทุกอย่างเรียบร้อยแล้ว เรารีบกลับโรงแรมกันเถอะ",
  ui_story_5004_50042601_6_dialog_content = "ราฟาเอล ฉัน แล้วก็ออโรเรียนคนอื่น ๆ บนโคลอสซัสจะหาวิธีรักษาฝันร้ายของเบริลเอง",
  ui_story_5004_50042601_7_dialog_content = "ใช่ เจเนวีฟเพื่อนเธอก็เส้นสายเยอะอยู่นะ ฉันว่าเธอหาคนมาช่วยได้แน่ ๆ",
  ui_story_5004_50042601_8_dialog_content = "หืม ทำไมอยู่ ๆ มาโยนให้ฉันล่ะเนี่ย? ฉันแค่มาช่วยสู้เฉย ๆ",
  ui_story_5004_50042601_9_dialog_content = "ชิ ก็ได้ ฉันรู้จักผู้เชี่ยวชาญด้านแร่ธาตุอยู่คนนึง เดี๋ยวจะลองถามให้นะ",
  ui_story_5004_50042601_10_dialog_content = "งั้นเรารีบเดินทางไปลูโมโพลิสกันเถอะ",
  ui_story_5004_50042601_11_dialog_content = "โบนาชี ช่วยพาเรากลับไปทีได้มั้ย?",
  ui_story_5004_50042601_12_dialog_content = "โบนาชี?",
  ui_story_5004_50042601_13_dialog_content = "เดี๋ยวก่อนนะ ฉันว่าฉันเจอปุ่มอะไรบางอย่างล่ะ",
  ui_story_5004_50042601_14_dialog_content = "ฮึบ",
  ui_story_5004_50042601_15_dialog_content = "สว่างชะมัด... ที่นี่ที่ไหนเนี่ย?",
  ui_story_5004_50042601_16_dialog_content = "(ทำไมทุกอย่างดูคุ้น ๆ จังแฮะ? หรือฉันจะเห็นภาพหลอน?)",
  ui_story_5004_50042601_17_dialog_content = "ไม่นะ PlayerName มีประตูออกมาปิดทางกลับ!",
  ui_story_5004_50042601_18_dialog_content = "หา?",
  ui_story_5004_50042601_19_dialog_content = "ไม่ไหว ทำยังไงก็ไม่ขยับเลย",
  ui_story_5004_50042601_20_dialog_content = "ล็อกดาวน์... เสร็จเรียบร้อย... <size=35>โปรดรีสตาร์ท...</size> <size=33>ระบบ...</size>",
  ui_story_5004_50042601_21_dialog_content = "...?",
  ui_story_5004_50042601_22_dialog_content = "ทุกคน มาลองเปิดประตูพร้อมกันนะ!",
  ui_story_5004_50042601_23_dialog_content = "ไม่ขยับเลยแม้แต่นิดเดียว ขนาดรวมพลังทุกคนโจมตีแล้วก็ยังทำอะไรไม่ได้",
  ui_story_5004_50042601_24_dialog_content = "นายว่ามันดูเหมือนภายในยานโคลอสซัสรึเปล่า PlayerName?",
  ui_story_5004_50042601_25_dialog_content = "ก็จริงนะ แต่จะเป็นไปได้ยังไงกัน? เอ๊ะ แล้วโบนาชีล่ะ?",
  ui_story_5004_50042601_26_dialog_content = "อยู่ไหนน้า~ อยู่ไหนน้า~",
  ui_story_5004_50042601_27_dialog_content = "บทเพลงอันล้ำค่าของฉัน~ ความรัก~ ความฝัน~ และทุก ๆ อย่างของฉัน~",
  ui_story_5004_50042601_28_dialog_content = "อิคลิพไซท์โสโครกพวกนั้นเอาไปซ่อนไว้ไหนกันนะ?",
  ui_story_5004_50042601_29_dialog_content = "นี่ไง <size=45>แจ็กพอต!</size>",
  ui_story_5004_50042601_29X1_dialog_content = "เอ๊ะ พวกแกสองคนมาทำอะไรที่นี่น่ะ?",
  ui_story_5004_50042601_29X2_dialog_content = "ชู่วว เดี๋ยวออโรเรียนพวกนั้นก็ได้ยินหรอก!",
  ui_story_5004_50042601_29X3_dialog_content = "เรามาเอาท่อนเพลงให้เธอน่ะสิ",
  ui_story_5004_50042601_29X4_dialog_content = "แสดงว่าเพลง... อยู่ในนี้งั้นเหรอ?",
  ui_story_5004_50042601_29X5_dialog_content = "ใช่ อย่าลืมล่ะ เธอต้องให้เคเลสไทต์...",
  ui_story_5004_50042601_29X6_dialog_content = "รู้แล้วน่า ให้เคเลสไทต์ปลดผนึกใช่มั้ย ฉันไม่ลืมหรอก",
  ui_story_5004_50042601_29X7_dialog_content = "เอาล่ะ ได้ท่อนเพลงครึ่งหลังมาแล้ว งั้นแกสองคนก็ไปพักผ่อนซะนะ?",
  ui_story_5004_50042601_29X8_dialog_content = "ระวังครับ ท่านพรินนี่!",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5004_50042601_29X10_dialog_content = "จากนั้นก็ลากไปเก็บที่มุมมืด... เพอร์เฟกต์!",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName! ยังอยู่รึเปล่า?</size>",
  ui_story_5004_50042601_31_dialog_content = "เราโดนขังอยู่ จะให้ไปไหนได้ล่ะ? แล้วนี่คุณไปไหนเนี่ย?",
  ui_story_5004_50042601_32_dialog_content = "ฉันเจอ<color=#FFB400>อะไรน่าสนใจด้วยล่ะ</color> มาดูสิ!",
  ui_story_5004_50042601_33_dialog_content = "นั่นอะไรน่ะ?",
  ui_story_5004_50042601_34_dialog_content = "ความรู้สึกแบบนี้ เหมือนมันเป็น<color=#FFB400>สิ่งประดิษฐ์ของเคเลสไทต์</color>เลย?",
  ui_story_5004_50042601_35_dialog_content = "ว่าแล้วว่านายจะต้องรู้",
  ui_story_5004_50042601_36_dialog_content = "ถ้านั่นเป็นสิ่งประดิษฐ์ของเคเลสไทต์ แล้วเราอยู่ในที่ที่เหมือนภายในยานโคลอสซัส... ก็แปลว่าเราเจอโคลอสซัสอีกลำงั้นเหรอ?",
  ui_story_5004_50042601_37_dialog_content = "ฉันจะไปรู้ได้ไงล่ะ? ฉันก็เป็นแค่นักดนตรีแล้วก็คนจัดงานคนนึง",
  ui_story_5004_50042601_38_dialog_content = "ทายาท... ที่ฉันเฝ้ารอมานาน...",
  ui_story_5004_50042601_39_dialog_content = "(อีกแล้ว)",
  ui_story_5004_50042601_40_dialog_content = "ลองใช้พลังจิตดูมั้ย PlayerName?",
  ui_story_5004_50042601_41_dialog_content = "รู้สึกสังหรณ์ใจไม่ดีเลยแฮะ PlayerName",
  ui_story_5004_50042601_42_dialog_content = "แต่เราโดนขังอยู่ จะทำอะไรได้อีกล่ะ?",
  ui_story_5004_50042601_43_dialog_content = "ก็ได้ งั้นระวังด้วยนะ",
  ui_story_5004_50042601_44_dialog_content = "ทายาท... ที่ฉันเฝ้ารอมานาน...",
  ui_story_5004_50042601_45_dialog_content = "เธอจะช่วงชิง<color=#FFB400>ท่อนเพลง</color>ไปไม่ได้... เด็ดขาด...",
  ui_story_5004_50042601_46_dialog_content = "จงอย่าเรียกมันออกมา...",
  ui_story_5004_50042601_47_dialog_content = "อย่าให้มัน... ทำลายโลกใบนี้...",
  ui_story_5004_50042601_48_dialog_content = "เฮ้ ประตูเปิดแล้ว!",
  ui_story_5004_50042701_49_dialog_content = "ขอบใจที่หากลไกเจอนะ ฉันถีบจนเมื่อยแล้วเนี่ย",
  ui_story_5004_50042701_50_dialog_content = "ว่าแต่คุณเอาอะไรออกมาเนี่ย โบนาชี?",
  ui_story_5004_50042701_51_dialog_content = "นั่นคือ \"ท่อนเพลง\" งั้นเหรอ",
  ui_story_5004_50042701_52_dialog_content = "นายรู้จักของพวกนี้ด้วยเหรอเนี่ย PlayerName? นี่คือส่วนหนึ่งของท่อนเพลงเทพเจ้าที่ฉันตามหาอยู่",
  ui_story_5004_50042701_53_dialog_content = "(เสียงที่ฉันได้ยินพูดถึงเจ้านี่สินะ)",
  ui_story_5004_50042701_54_dialog_content = "คุณรู้ได้ไงว่ามันอยู่ในนี้? แล้วอิคลิพไซท์พวกนั้นมาจากไหน?",
  ui_story_5004_50042701_55_dialog_content = "เห็นชัด ๆ เลยว่าพวกมันคอยปกป้องท่อนเพลงอยู่",
  ui_story_5004_50042701_56_dialog_content = "โอ้ ฉลาดเหมือนกันนี่ เคเลสไทต์",
  ui_story_5004_50042701_57_dialog_content = "ใช่แล้ว ฉันตกลงอะไรเล็ก ๆ น้อย ๆ กับพวกอิคลิพไซท์",
  ui_story_5004_50042701_58_dialog_content = "เธอร่วมมือกับอิคลิพไซท์งั้นเหรอ?",
  ui_story_5004_50042701_59_dialog_content = "หืม? ฉันไม่ได้จะเป็นเพื่อนกับมันนะ แล้วก็ไม่ได้ช่วยพวกมันทำเรื่องชั่ว ๆ ซักหน่อย",
  ui_story_5004_50042701_60_dialog_content = "พวกมันสัญญาว่าจะให้ท่อนเพลงกับฉัน ส่วนฉันก็แค่จัดงานราชันเจ้าสมุทรให้พวกมัน",
  ui_story_5004_50042701_61_dialog_content = "ราชันเจ้าสมุทร? งานนี้เป็นแผนของอิคลิพไซท์เหรอนเนี่ย?",
  ui_story_5004_50042701_62_dialog_content = "เรื่องนั้นฉันไม่สนหรอก เสียงในหัวของฉันและเพลงบทนี้มันสำคัญกว่านั้นเยอะ",
  ui_story_5004_50042701_63_dialog_content = "นี่คุณเป็นนักดนตรีจิตหลุดหรือไงกัน? โอ๊ะ! ก็ใช่นี่นา!",
  ui_story_5004_50042701_64_dialog_content = "ในเมื่อคุณได้เพลงไปแล้ว คุณจะทำอะไรต่อ? จะร่วมมือกับอิคลิพไซท์งั้นเหรอ?",
  ui_story_5004_50042701_65_dialog_content = "ก็บอกไปแล้วไงว่าฉันไม่ได้จะเป็นเพื่อนกับมัน ก็แค่เรามีผลประโยชน์ร่วมกัน! ที่จริงฉันวางแผนจะให้มันกับนายนี่แหละ PlayerName!",
  ui_story_5004_50042701_66_dialog_content = "ให้ผม? หลังจากที่คุณลำบากตามหามันแทบตายเนี่ยนะ?",
  ui_story_5004_50042701_67_dialog_content = "ก็นะ ยังไงมันก็เป็น<color=#FFB400>รางวัลใหญ่</color>ของงานราชันเจ้าสมุทรนี่นา",
  ui_story_5004_50042701_68_dialog_content = "ฉันเก็บเรื่องนี้เป็นความลับไม่บอกพวกนาย ก็เลยจะยกท่อนเพลงให้เพื่อเป็นการไถ่โทษ แบบนี้ถือว่าเจ๊ากันใช่มั้ยล่ะ แต่ขอฉันเล่นมันก่อนได้มั้ย",
  ui_story_5004_50042701_69_dialog_content = "มันเหมือนกับว่าทุกคนเหนื่อยเก็บผลไม้อร่อย ๆ มาด้วยกัน แต่คุณกลับได้กัดคำแรกก่อนเลยแฮะ",
  ui_story_5004_50042701_70_dialog_content = "อย่าพูดแบบนั้นเลยน่า เราเป็นเพื่อนกันไม่ใช่เหรอ ดูนี่สิ...",
  ui_story_5004_50042701_71_dialog_content = "หืม ยังมีเพลงอีกท่อนที่เหมือนกับเปี๊ยบเลย?",
  ui_story_5004_50042701_72_dialog_content = "ใช่แล้ว เราต้องนำครึ่งแรกมารวมกับครึ่งหลังเพื่อให้ได้บทเพลงที่สมบูรณ์",
  ui_story_5004_50042701_73_dialog_content = "เอ๊ะ...",
  ui_story_5004_50042701_74_dialog_content = "มีแสงวูบเดียว? แค่นี้เองเหรอ?",
  ui_story_5004_50042701_75_dialog_content = "เกิดอะไรขึ้นน่ะ?",
  ui_story_5004_50042701_76_dialog_content = "ฉันสัมผัสได้ว่าในนั้นมีพลังงานบางอย่างอยู่ แต่มันถูกขัดขวางเอาไว้",
  ui_story_5004_50042701_77_dialog_content = "(ยังไม่ได้ผลเหรอ? สงสัยต้องลองอย่างที่<color=#FFB400>เจ้าแฮมสเตอร์นั่น</color>บอก...)",
  ui_story_5004_50042701_78_dialog_content = "นายช่วยลองหน่อยสิ PlayerName ทำอะไรสักอย่าง ใช้พลังจิตหรืออะไรก็ได้",
  ui_story_5004_50042701_79_option_content = "ไม่มีทาง",
  ui_story_5004_50042701_80_dialog_content = "ฉันจะไม่แตะต้องของที่ได้จากการร่วมมือกับอิคลิพไซท์หรอกนะ!",
  ui_story_5004_50042701_81_dialog_content = "ก็ได้ ก็ได้ ฉันสาบานว่าจะไม่ยุ่งเกี่ยวกับอิคลิพไซท์อีกแล้ว!",
  ui_story_5004_50042701_82_option_content = "ในเมื่อคุณให้ผม...",
  ui_story_5004_50042701_83_dialog_content = "แต่ยังไงผมก็ไม่เล่นให้หรอก!",
  ui_story_5004_50042701_84_dialog_content = "สัญชาตญาณของผมบอกว่ามันต้องมีเรื่องน่ากลัวแน่ ๆ!",
  ui_story_5004_50042701_85_dialog_content = "มันจะน่ากลัวแค่ไหนเชียว? ทุกคนก็อยู่พร้อมช่วยนายอยู่แล้วนะ นะนะ ได้โปรดเถอะ!",
