  ui_story_5004_50042701_87_dialog_content = "แต่ผมได้ยินเสียงเตือนว่าอย่าคลายผนึกเด็ดขาด",
  ui_story_5004_50042701_88_dialog_content = "ฟังผิดรึเปล่า? ไม่เอาน่า ช่วยฉันทีเถอะนะ",
  ui_story_5004_50042701_89_dialog_content = "คุณต้องสาบานก่อนว่าจะไม่ยุ่งเกี่ยวกับอิคลิพไซท์อีก",
