  ui_story_5004_50042701_171_dialog_content = "เหวอ โผล่มาจากไหนน่ะ?",
  ui_story_5004_50042701_172_dialog_content = "ฉันก็อยู่แถว ๆ นี้แหละ วิ่งตามพวกนายตอบคลื่นซัดด้วย ไม่ได้สังเกตเลยเหรอ",
