  ui_story_5004_50042701_178_dialog_content = "ไม่ต้องห่วง ฉันจะไม่เล่นมันอีกแล้ว เพราะงั้นช่วยยกโทษให้ฉันได้มั้ย ฮิฮิ~",
  ui_story_5004_50042701_179_dialog_content = "(จะเอาตัวรอดง่าย ๆ ยังงี้เลยเรอะ...?)",
  ui_story_5004_50042701_180_dialog_content = "เราต้องหาที่เก็บของอันตรายแบบนั้นให้ดี ๆ นะ",
  ui_story_5004_50042701_181_dialog_content = "ถ้าปล่อยไว้จะต้องมีคนเอาไปทำอะไรไม่ดีแน่ ๆ",
  ui_story_5004_50042701_182_dialog_content = "นั่นสิ... ฉันจะรับมันไว้ แต่อย่าคิดว่าจะรอดพ้นความผิดไปง่าย ๆ นะ!",
  ui_story_5004_50042701_183_dialog_content = "เล่าทุกอย่างมาซะ คุณไปตกลงอะไรกับอิคลิพไซท์เอาไว้บ้าง?",
