  ui_story_5004_50042801_E4_dialog_content = "โอเค...",
  ui_story_5004_50042801_E5_dialog_content = "ตื่นจากนิทราจนได้นะคะ นายท่าน...",
  ui_story_5004_50042801_E6_dialog_content = "ว่าอย่างไรนะคะ? ท่านต้องการพบนักรบที่ปลุกท่านขึ้นมาอย่างนั้นรึ?",
  ui_story_5004_50042801_E7_dialog_content = "หืม ทุกคนได้ยินเสียงอะไรรึเปล่า? อยู่ ๆ มันก็แว่วเข้ามาในหูน่ะ",
  ui_story_5004_50042801_E8_dialog_content = "รับทราบค่ะ หึหึ ฉันเชื่อว่าพวกมันก็อยากจะพบท่านเต็มแก่เช่นกัน...",
  ui_story_5004_50042801_E9_dialog_content = "แต่ตอนนี้พลังของท่านยังไม่ฟื้นกลับมาอย่างสมบูรณ์ ดังนั้น ขอฉันช่วยท่านเถอะนะคะ",
  ui_story_5004_50042801_E10_dialog_content = "เสียงอะไรเหรอ? ฉันยังสลัดเพลงนั่นออกจากหัวไม่ได้เลย... แต่เหมือนพลังความมืดอยู่ ๆ ก็พุ่งสูงขึ้น!",
  ui_story_5004_50042801_E11_dialog_content = "มาจากไหนกันนะ? เมื่อกี้ยังไม่เห็นมีเลย!",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>\"เมื่อบทเพลงได้บรรเลง การค้นหาจักสิ้นสุดลง องค์ราชันลุกตื่นจากการหลับใหล เพียงเพื่อจะปลดปล่อยความคั่งแค้น แผดเผาดวงดาราให้มอดไหม้ และนำความพินาศมาสู่ทุกสรรพสิ่ง\"</color>",
  ui_story_5004_50042801_E13_dialog_content = "...",
  ui_story_5004_50042801_184_dialog_content = "กรรร!",
  ui_story_5004_50042801_185_dialog_content = "อิคลิพไซท์ที่หนีจากการต่อสู้เมื่อกี้เหรอ?",
  ui_story_5004_50042801_186_dialog_content = "ไม่ใช่ พวกมันคือ...!",
  ui_story_5004_50042802_1_dialog_content = "แข็งแกร่งจริง ๆ... เหนือกว่าอิคลิพไซท์ทั่วไปคนละชั้นเลย",
  ui_story_5004_50042802_2_dialog_content = "พวกมันมาจากไหนน่ะ? ฉันไม่เคยเจออะไรแบบนี้มาก่อนเลย",
  ui_story_5004_50042802_3_dialog_content = "ดีนะที่เราจัดการได้ พวกมันออกไปทำเรื่องชั่ว ๆ ไม่ได้แล้วล่ะ",
  ui_story_5004_50042802_4_dialog_content = "ไม่หรอก... ฉันว่านี่น่าจะเป็นแค่ร่างจำลอง",
  ui_story_5004_50042802_5_dialog_content = "ระหว่างที่สู้เมื่อกี้ ฉันสัมผัสได้ว่ามีพลังที่แข็งแกร่งกว่านั้นควบคุมพวกมันอยู่",
  ui_story_5004_50042802_6_dialog_content = "แล้วมันก็มาจากปราสาทนั่น",
  ui_story_5004_50042802_7_dialog_content = "(ฉันมัวแต่สนเรื่องอื่นจนเกือบลืมปราสาทมหึมานั่นไปเลย)",
  ui_story_5004_50042802_8_dialog_content = "(ตอนนี้สัมผัสได้ชัดเจนเลยว่ามันปล่อยพลังความมืดอันน่ากลัวจำนวนมหาศาลออกมา)",
  ui_story_5004_50042802_9_dialog_content = "ชิ... ผลงานของอิคลิพไซท์พวกนั้นเหรอเนี่ย? โดนหลอกซะได้...",
  ui_story_5004_50042802_10_dialog_content = "ก็ว่าอยู่ ทำไมพวกมันถึงให้ท่อนเพลงกับฉันง่ายเหลือเกิน มันอยากใช้พลังของ PlayerName กับฉันเรียกของแบบนั้นออกมาสินะ!",
  ui_story_5004_50042802_11_dialog_content = "งานราชันเจ้าสมุทรไม่ใช่แค่แผนหลอกฟันเงินนักท่องเที่ยวเหรอเนี่ย เจ้าแฮมสเตอร์นั่นวางแผนทุกอย่างไว้หมดแล้ว!",
  ui_story_5004_50042802_12_dialog_content = "ไม่เป็นไร คราวหน้าถ้าเจอฉันจะซ้อมให้น่วมแล้วแย่งท่อนเพลงมา!",
  ui_story_5004_50042802_13_dialog_content = "หลอกฟันเงิน? อิคลิพไซท์จะเอาเงินไปทำอะไรน่ะ?!",
  ui_story_5004_50042802_14_dialog_content = "พวกมันบอกว่าจะดูดเงินจากกระเป๋าออโรเรียนให้แห้ง พอออโรเรียนยากจน ก็ต้องทำงานหนักหาเงินจนไม่มีปัญญาต่อกรกับอิคลิพไซท์...",
