  ui_story_5004_50042802_17_dialog_content = "คาร์ลีนพูดถูก ไม่งั้นทุกคนที่ชายหาดอาจจะตกอยู่ในอันตราย หรือไม่ก็อาจเกิดเรื่องเลวร้ายกว่านั้น",
  ui_story_5004_50042802_18_dialog_content = "อุตส่าห์มาถึงนี่แล้ว คงไม่ปอดแหกกลัวอิคลิพไซท์จนหนีไปหรอกนะ?",
  ui_story_5004_50042802_19_dialog_content = "ก็แค่อิคลิพไซท์ไม่กี่ตัว อัดให้น่วมแล้วจับไปแลกค่าหัวดีกว่า",
  ui_story_5004_50042802_20_dialog_content = "เอ่อ... ฉันก็อยากไปด้วยค่ะ... ปราสาทนั่นทำให้ฉันกังวลมากเลย...",
  ui_story_5004_50042802_21_dialog_content = "ถ้าเจ้าเบริลไป ฉันก็ต้องไปด้วย",
  ui_story_5004_50042802_22_dialog_content = "ทำไมมองฉันแบบนั้นล่ะ? ฉันเป็นหัวหน้าหน่วยรักษาความปลอดภัยนะ! ยังไงก็มันก็เป็นหน้าที่ฉันอยู่แล้ว!",
