  ui_story_5004_50042802_24_dialog_content = "ช่วยไม่ได้นะ เพื่อเป็นการไถ่โทษ ฉันจะใช้อะไหล่โบราณแสนล้ำค่าที่หามาได้ ช่วยซ่อมหุ่นให้นายเอง",
