  ui_story_5004_50043201_28_dialog_content = "แต่บันทึกนี่ก็อธิบายอย่างละเอียด ว่าฉันเป็นอิสระแล้วก็มีความสุขแค่ไหนหลังจากได้เป็นอิคลิพไซท์",
