  ui_story_5004_50043201_30_dialog_content = "กลับเข้าเรื่องก่อนดีกว่า อย่างที่บอกไป ตระกูลของเธอต่างจากตระกูลฉันมาก ๆ พวกเธอแค่อยากใช้คริสตัลเป็นแหล่งพลังงาน...",
  ui_story_5004_50043201_31_dialog_content = "พลังอันโหดเหี้ยมป่าเถื่อนขนาดนี้ควรจะเอามาใช้เป็นอาวุธสิ!",
  ui_story_5004_50043201_34_dialog_content = "มันจะเป็นดาบอันคมกริบที่ช่วยขับไล่อิคลิพไซท์ให้พ้นไปจากลูโมโพลิส อาจส่งอิคลิพไซท์กลับสู่ก้นบึ้งแห่งความมืดมิดได้ด้วยซ้ำ!",
  ui_story_5004_50043201_35_dialog_content = "แต่ตระกูลขี้ขลาดของเธอก็เอาเรื่องนี้ไปฟ้องเจ้าเมือง! ให้ตายสิ พออ่านถึงตรงนี้ก็เริ่มโมโหขึ้นมาอีกแล้ว!",
  ui_story_5004_50043201_36_dialog_content = "ตระกูลไพรัสของพวกแกออกล่าออโรเรียนยากจนหรือตกอับ ลักพาตัวพวกเขามาทดลองกับคริสตัล",
  ui_story_5004_50043201_37_dialog_content = "ไม่มีคนสติดีคนไหนทำการทดลองกับเผ่าพันธุ์เดียวกันแบบนั้นหรอก!",
  ui_story_5004_50043201_38_dialog_content = "ฉันยอมรับว่าตอนสาว ๆ ฉันหมกมุ่นกับการทดลองเรื่องคริสตัลจริง ๆ",
  ui_story_5004_50043201_39_dialog_content = "แต่ถ้าไม่มีฉัน ก็คงไม่มีเบริล... ตัวทดลองที่ฉันภาคภูมิใจที่สุด อย่างที่พวกเธอเห็นในตอนนี้ ...",
  ui_story_5004_50043201_40_dialog_content = "อย่าบอกนะ ว่าเจ้าเบริล...",
  ui_story_5004_50043201_41_dialog_content = "...",
  ui_story_5004_50043201_42_dialog_content = "สมุดบันทึกของฉันมีข้อมูลของเธอละเอียดมาก ๆ ไม่ว่าจะเป็นอาหารจานโปรด กีฬาที่ชอบ...",
  ui_story_5004_50043201_43_dialog_content = "หรือแม้แต่ของที่เธอชอบกอดตอนนอน",
  ui_story_5004_50043201_44_dialog_content = "เหมือนกับว่าคนเขียนตกหลุมรักเธอยังงั้นแหละ!",
  ui_story_5004_50043201_45_dialog_content = "เดี๋ยวนะ ฉันเป็นคนเขียนเองนี่นา แสดงว่าฉันเป็นพวกโรคจิตที่ตกหลุมรักเด็กสาวผู้ใสซื่อใช่มั้ยเนี่ย",
