  ui_story_5004_50043201_47_dialog_content = "ฉันมอบความรักให้เธอไปมากมาย~",
  ui_story_5004_50043201_48_dialog_content = "ผงคริสตัลพิเศษที่สร้างจากพลังความมืดยังคงเติบโตในร่างกายของเธอใช่มั้ย?",
  ui_story_5004_50043201_49_dialog_content = "มันอาศัยอยู่ในตัวเธอ กัดกินอารมณ์ความรู้สึกของเธอเป็นอาหาร",
