  ui_story_5004_50043201_51_dialog_content = "แต่พลังของมันควบคุมยากมาก ๆ... ฮิฮิ นี่ล่ะเป็นตอนที่ฉันชอบที่สุด!",
  ui_story_5004_50043201_52_dialog_content = "อา~ ไฟกองโตที่เธอจุดขึ้นมา และเสียงโหยหวนของเหยื่อนับไม่ถ้วนที่เธอลงมือฆ่า...",
