  ui_story_5004_50043201_70_dialog_content = "ฉันแทบจะไม่แน่ใจเกี่ยวกับอดีตในส่วนนั้นเลย...",
  ui_story_5004_50043201_71_dialog_content = "ฉันจำได้แค่ว่าตระกูลไพรัสลักพาตัวฉันไปตั้งแต่ยังเด็กมาก ๆ",
  ui_story_5004_50043201_72_dialog_content = "พวกนั้นขังฉันในห้องมืดสนิท... แล้วก็ป้อนผงคริสตัลให้ฉัน",
  ui_story_5004_50043201_73_dialog_content = "จากนั้นร่างกายของฉันก็เปลี่ยนไปเหมือนกับถูกสาป... ไม่อาจหลุดพ้นจากคริสตัลที่ทำให้ฉันทุกข์ทรมาน",
