  ui_story_5004_50043301_3_dialog_content = "\"นี่เป็นร่างใหม่ที่สร้างขึ้นจากคริสตัล... ซึ่งเป็นพลังแบบเดียวกับเธอยังไงล่ะ เบริล\"",
  ui_story_5004_50043301_4_dialog_content = "\"แต่ที่ไม่เหมือนกันก็คือ เธอมันเป็นแค่ตัวต้นแบบ ส่วนฉันคือผลการทดลองที่สมบูรณ์ สามารถควบคุมพลังของคริสตัลได้อย่างเต็มรูปแบบ\"",
  ui_story_5004_50043301_5_dialog_content = "\"และ<color=#FFB400>กษัตริย์ผู้โดดเดี่ยว</color>ก็จะคืนชีพขึ้นมาด้วยพลังแห่งคริสตัล และปกครองทุกสรรพสิ่งอีกครั้ง\"",
  ui_story_5004_50043301_6_dialog_content = "อะแฮ่ม นี่เป็นบทนำของเพลงอาลัยที่ฉันเขียนขึ้นมาเพื่อบันทึกเรื่องราวความตายอันแสนสลดของพวกเธอ ชอบมั้ยล่ะ?",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>แคโรไลน์โบกมือของเธอ ทำให้คริสตัลแตกสลายกลายเป็นผงและก่อตัวเป็นหมอกทึบ จากนั้นกษัตริย์ก็ดูดซับผงคริสตัลเข้าไป</color>",
